// colour of a number = the school of the biggest hit in it
const DMG_COL = { frost: '#9fe0ff', fire: '#ffae4a', poison: '#9dff6a', storm: '#c9e4ff', arcane: '#e0b0ff', holy: '#fff09a', shadow: '#d29cff', earth: '#ffd9a0', phys: '#ffffff', magic: '#ffffff', pure: '#ffffff' };
