// ids in list order (as core.js does for TALENTS), and a check that every req points straight up one row
for (const k in GROVE_TALENTS) {
  const L = GROVE_TALENTS[k].list;
  L.forEach((t, i) => t.id = i);
  for (const t of L) if (t.req) {
    const q = L.find(o => o.r === t.req[0] && o.c === t.req[1]);
    if (!q || q.c !== t.c || q.r !== t.r - 1) console.warn('GROVE_TALENTS: bad req', k, t.name);
  }
}

// the talent panel's per-tree flavour (TAL_FLAVOR's shape: [subtitle, lore line]) and tab emblem (TAL_EMBLEM's shape:
// an index into the list), to use in place of the towers' while the Grove is active
const GROVE_TAL_FLAVOR = {
  glaive: ['Hold the lanes with spear and living thorn-shield.', 'The wood does not yield. Neither do we.'],
  arrow: ['Loose leaf-fletched arrows from the boughs, swift and sure.', 'Let the roots hold them. Then loose.'],
  frost: ['Wake the roots beneath the road and hold the horde fast.', 'Every root is patient. Every root is strong.'],
  arcane: ['Ride out on the great stags and bring down the mighty.', 'The stag does not ask the hunter. It decides.'],
  storm: ['Take the shape the fight needs: hawk, bear or sage.', 'The wood wears many skins. So do we.'],
  earth: ['Whirl through the horde on twin leaf-blades.', 'Never stop moving. The dance is the blade.'],
  cannon: ['Sow bursting seedpods and let the spores do the rest.', 'Plant once. The wood will finish it.'],
};
const GROVE_TAL_EMBLEM = {};
for (const [k, nm] of Object.entries({ glaive: 'Wall of Spears', arrow: 'Pinning Shot', frost: 'Deep Roots', arcane: 'Heavy Lance',
  storm: 'Skyfall', earth: 'Bladestorm', cannon: 'Potent Spores' })) GROVE_TAL_EMBLEM[k] = GROVE_TALENTS[k].list.findIndex(t => t.name === nm);
FORCES.grove.talents = GROVE_TALENTS; FORCES.grove.talFlavor = GROVE_TAL_FLAVOR; FORCES.grove.talEmblem = GROVE_TAL_EMBLEM;   // (applyForce swaps the trees in; the talent panel reads the rest)

/* ================= TOWER PATHS: at tier IV every tower chooses one of two paths =================
   Tiers I-III are a straight climb. Upgrading to tier IV asks which path this one tower takes; its tier V and VI perks
   then follow that path. Talents shape every tower of a type; a path shapes one tower, so two towers of the same type
   can do different jobs. Each perk: text, plus how it changes the stats (mul, add, set) and the caps it switches on
   (read by the game code where the tower fires, hits and ticks). */
