          part({ k: 'flare', x: c.x, z: c.y, h: hitH(c), life: .25, max: .25, size: 1.1, col: ab.hue }); fxSpark(c.x, c.y, hitH(c), '#ffe9b0', 16);
          if (abBig(c)) G.hitStop = Math.max(G.hitStop || 0, .04);
