  const fake = { tier: 0, def: TOWERS[ty] }, st0 = TOWERS[ty].tiers[0];
  s[0] = { key: `t:${ty}:0`, lbl: TOWERS[ty].short, on: true, name: TOWERS[ty].blurb, act: () => onToast(TOWERS[ty].blurb) };
  kit.abilities.forEach((ab, n) => { s[4 + n] = loreSlot(u, ab, 'QWE'[n], abText(fake, st0, ab) + (AB_PREF[ab.id] ? ` Favours ${AB_PREF_SAY[AB_PREF[ab.id]]}.` : ''), false); });
