  const o = { l: A.learned.slice(), o: Object.keys(A.auto).filter(id => A.auto[id] === false), m: A.mode === 'focus' ? 1 : 0, f: A.focus || 0, n: Math.round(A.mana) };
  if (t.form) o.fm = t.form; if (A.formLock) o.fk = A.formLock;   // a Grove Shifter's form, and the one it holds
