  const c = s.cur; if (c && ABIL[c.id] && ABIL[c.id].unit === c.u && !L.done[loreKey(c.u, c.id)]) L.cur = { u: c.u, id: c.id, t: Math.max(0, +c.t || 0), T: Math.max(.1, +c.T || 1) };
  return L;
