function srQuake(s) {
  const tot = G.towers.filter(t => t.type === 'earth' && !t.wrecked), n = Math.min(8, tot.length); if (!n) return;
  const avg = tot.reduce((a, t) => a + ((t.st && t.st.dmg) || 30), 0) / tot.length, dmg = avg * .3 * s.k * n, dur = Math.min(2, .25 * n), src = s.t;
  tagged('relic', () => { for (const c of G.creeps.slice()) { if (c.dead || c.fly) continue; hurt(c, dmg, 'phys', src, false, null, 'earth'); if (!c.dead) stun(c, dur, .4, 'earth'); } });
  const P = G.path && G.path.pts ? G.path.pts : [];
  for (let k = 0; k < P.length; k += Math.max(1, Math.floor(P.length / 12))) { fxQuake(P[k][0], P[k][1], .9, .6); if (k % 2 === 0) fxDust(P[k][0], P[k][1], 4); }
  G.shake = Math.max(G.shake, .45); flashLight(5.5, 6.5, .4, [1.2, .9, .5], 8, .3); sfx('quake', 2);
}

/* ================= GROVE ITEMS: the Grove's own relics, legendaries, charms and shop =================
   While a force leads the keep, only its own items drop and stand on the shop's shelf (LOOT_POOL, swapped by applyForce
   as the talent trees are; POOL_BASE is the keep's own pool, taken here before anything of the Grove's is registered).
   Every definition stays registered in GEAR_BASES / LEGENDS / SHOP, so an item from either pool loads, sockets and works
   whatever the run: only what is offered changes.
   The rules are the tower relics' (loot.js): hand-made items, one rule you can say in a sentence and an effect you can
   see, no random stats and no random procs. Drops start at rare (blue) as the tower relics do; the old common and
   uncommon tiers live on as bigger numbers (kx): kx 1.6 sharpens what a unit does, kx 1.35 adds a habit, a plain rare
   bends a rule, an epic makes a moment, a legendary changes how a unit plays. Signature legendaries and unit relics fit
   one unit (for: its slot) and drop for the units you field.
   Charms are a new kind: they work on a unit's mana and abilities (abilities.js) and sit in its own charm socket (the
   Gear page's fourth socket, open from tier II), never in a relic socket. They are GEAR_BASES entries with charm: 1, so
   naming, honing, salvage and saves are a relic's; they give no flat damage spike (their power is the rule).
   The Grove's relics set st.pw.gv, which routes the tower relic hooks (relicOnHit, relicTick) here; force units also
   call groveFire (fire), groveOnKill (kill), groveLive (effStats) and groveAmp (hurt), and abilities.js asks charmCost,
   charmCdK, manaRegenK and groveOnCast. Painted icons come from groveart.js (GROVEART, by id) when they exist. */

/* ---------- the pools ---------- */
const poolOf = (bases, legends, shop, o) => Object.assign({ bases: new Set(bases), legends: new Set(legends), shop: new Set(shop), school: true, tomes: true, cat: true, charms: false }, o || {});
const POOL_BASE = poolOf(Object.keys(GEAR_BASES), Object.keys(LEGENDS), Object.keys(SHOP));   // the keep's own (before the Grove's register)

/* ---------- small helpers ---------- */
function gvPw(st, k, v) { pwMax(st, k, v); st.pw.gv = 1; }
function gvMin(st, k, v) { pwMin(st, k, v); st.pw.gv = 1; }
const gvNear = (x, z, r, filt) => { const out = []; for (const c of G.creeps) if (!c.dead && !c.ent && !c.phased && Math.hypot(c.x - x, c.y - z) <= r && (!filt || filt(c))) out.push(c); return out; };
const gvWalks = c => !c.fly || c.lowT > G.time;
const gvHoldable = c => !c.fly && !(c.rootT > G.time) && !(c.ccImm > G.time) && !(c.burT > 0);
const gvBig = c => !!(c.def.boss || c.def.lead || c.elite);
const gvUnits = (x, z, r, skip) => G.towers.filter(o => o !== skip && !o.def.wall && !o.wrecked && !(o.build > .5) && Math.hypot(o.x - x, o.y - z) <= r);
const gvAlive = t => G.state === 'play' && G.towers.includes(t) && !t.wrecked;
function gainMana(o, n) { if (!(n > 0) || typeof abilEnsure !== 'function') return; if (VET_ACT && VET_ACT !== o) vetAid(o, VET_ACT, 3); const A = abilEnsure(o); if (A) A.mana = Math.min(abMax(o), A.mana + n); }
function gvLeaves(x, z, h, n, col) { for (let k = 0; k < n; k++) part({ k: 'spark', x, z, h, vx: R(-1.5, 1.5), vz: R(-1.5, 1.5), vh: R(.3, 1.4), g: 3, drag: 2, life: .5, max: .5, size: R(.04, .07), col: col || (k % 3 ? '#9be05a' : '#d8e890') }); }
function gvMotes(x, z, h, n, col) { for (let k = 0; k < n; k++) part({ k: 'spark', x: x + R(-.2, .2), z: z + R(-.2, .2), h, vx: 0, vz: 0, vh: R(.5, 1), g: -.2, life: .7, max: .7, size: .04, col }); }
function gvFeathers(x, z, h, n) { for (let k = 0; k < n; k++) part({ k: 'spark', x, z, h, vx: R(-1.2, 1.2), vz: R(-1.2, 1.2), vh: R(-.2, 1.2), g: 1.5, drag: 2.5, life: .6, max: .6, size: R(.04, .07), col: k % 2 ? '#7a5a3a' : '#e8dcc0' }); }
function gvRootFx(c, n) { for (let k = 0; k < n; k++) part({ k: 'chunk', x: c.x + R(-.18, .18), z: c.y + R(-.18, .18), h: .05, vh: R(.8, 1.5), vx: R(-.35, .35), vz: R(-.35, .35), g: 7, life: .4, max: .4, size: R(.03, .055), col: k % 2 ? '#4a7a2a' : '#5a4430' }); }
const MANA_COL = '#7ab8ff';

