  if (p.ribbon && n % 4 === 0) G.delayed.push({ t: .08, fn: () => gvRibbon(t, t.st || st, p.ribbon) });   // Leafsong Ribbon
  if (p.hood && n % 4 === 0 && !tg.dead && typeof hawkFly === 'function') {   // Gyrfalcon Hood: the hawk stoops on it
    const dl = t.def.unit === 'wayfarer' ? hawkFly(t, tg) : .3, m = p.hood;
    G.delayed.push({ t: dl, fn: () => { if (tg.dead || !gvAlive(t)) return; tagged('relic', () => hurt(tg, ((t.st || st).dmg || 0) * m, 'phys', t, false, null)); gvFeathers(tg.x, tg.y, hitH(tg), 8); relicGlint(t, 'gv_hood'); } });
  }
