  for (let k = 0; k < 14; k++) { const a = k / 14 * TAU; part({ k: 'spark', x: t.x + Math.cos(a) * .5, z: t.y + Math.sin(a) * .5, h: .45, vx: -Math.sin(a) * 2.6 + Math.cos(a) * .8, vz: Math.cos(a) * 2.6 + Math.sin(a) * .8, vh: .2, g: 0, drag: 1, life: .35, max: .35, size: .055, col: k % 2 ? '#9be05a' : '#d8e890' }); }
