    for (const q of sp) if (o.poison.length < 3) { o.poison.push({ dps: q.dps, t: Math.max(2, q.t), src: q.src }); rfx({ k: 'streak', x0: c.x, h0: hitH(c), z0: c.y, x1: o.x, h1: hitH(o), z1: o.y, col: '#9ab83a', w: .05, life: .3 }); }
