  for (let k = 0; k < 12; k++) part({ k: 'smoke', x: c.x + R(-.2, .2), z: c.y + R(-.2, .2), h: hitH(c) * .7, vx: R(-1.4, 1.4), vz: R(-1.4, 1.4), vh: R(.2, .7), drag: 2, life: .6, max: .6, size: R(.12, .22), col: '#9ab83a' });
