    for (let k = 0; k < 10; k++) part({ k: 'smoke', x: c.x + R(-.2, .2), z: c.y + R(-.2, .2), h: hitH(c) * .6, vx: R(-1, 1), vz: R(-1, 1), vh: R(.2, .6), drag: 2, life: .7, max: .7, size: R(.12, .2), col: '#b8c060' });
