  cc_rimeweaver: { robe: '#2c2a6a', robeD: '#1c1a44', robeL: '#3a3684', trim: '#9ab0e8', skin: '#e6cfc4', hair: '#1c1a30', glow: '#a8ecff', crystal: '#8fe0ff', fur: '#f4f8ff', hood: '#2a2258', pattern: '#7486d8' },
  cc_chronomancer: { robe: '#4e2470', robeD: '#30164a', robeL: '#6a3492', trim: '#e2b850', skin: '#e0b896', hair: '#f4f2ee', hairD: '#d8d6d2', glow: '#7fe8ff', gold: '#d8a83c', brass: '#a87a2a', sand: '#9ff0ff', silver: '#c4c8d8' },
