        const L = abLine(t, st, t.x, t.y, ux, uz, ab.len, .4, abWalker).sort((a, b) => abDist(t, a) - abDist(t, b));
        abAoe(() => L.forEach((o, i) => { ccAb(t, st, o, m, k); if (!o.dead) { chill(o, { slow: .4, slowT: 2 }, 'frost', t); if (!i) ccFreeze(t, o, .5); } }));
        rfx({ k: 'streak', x0: t.x, h0: .45, z0: t.y, x1: t.x + ux * ab.len, h1: .35, z1: t.y + uz * ab.len, col: '#c8f4ff', w: .09, trav: .1, life: .4 });
        for (let q = 0; q <= 6; q++) { const f = q / 6 * ab.len; fxShards(t.x + ux * f, t.y + uz * f, .35, 2); }
        sfx('shatter', 0);
