for (const k in CC_TALENTS) {
  const L = CC_TALENTS[k].list; L.forEach((t, i) => t.id = i);
  for (const t of L) if (t.req) { const q = L.find(o => o.r === t.req[0] && o.c === t.req[1]); if (!q || q.c !== t.c || q.r !== t.r - 1) console.warn('CC_TALENTS: bad req', k, t.name); }
}
const CC_TAL_FLAVOR = {
  glaive: ['Cut, blink and cut again: the duellist\'s art of the College.', 'A blade is only a spell that stays.'],
  arrow: ['Teach the apprentices to loose a storm of seeking missiles.', 'Again. Faster. Now the other hand.'],
  frost: ['Write the cold onto the road and let the road do the rest.', 'Every glyph is a sentence. Every sentence ends.'],
  arcane: ['Bend the hours: slow the horde, hasten the Conclave, rewind the wrong.', 'We have all the time they lack.'],
  storm: ['Read the night sky and call its stars down on the horde.', 'The heavens keep an honest ledger.'],
  earth: ['Wake the stone, and teach it to strike where it is told.', 'Patience is a mountain\'s only spell.'],
  cannon: ['Throw fire, and leave the road burning behind it.', 'Fire is a fine teacher. Few pass twice.'],
};
const CC_TAL_EMBLEM = {};
for (const [k, nm] of Object.entries({ glaive: 'Starsteel', arrow: 'Echoing Missiles', frost: 'Entomb', arcane: 'Paradox', storm: 'Comet', earth: 'Deep Magma', cannon: 'Ember Heart' })) CC_TAL_EMBLEM[k] = CC_TALENTS[k].list.findIndex(t => t.name === nm);
FORCES.conclave.talents = CC_TALENTS; FORCES.conclave.talFlavor = CC_TAL_FLAVOR; FORCES.conclave.talEmblem = CC_TAL_EMBLEM;

// Unstable Charge (the Magelings' capstone): when the charge fills, a free Arcane Barrage at 60%; 2 charges kept
function ccUnstable(t) {
  ccEv('cap:ccUnstable');
  const ab = ABIL.cc_barrage; if (!ab || !t.ab || !ccAlive(t) || t.silT > 0 || G.state !== 'play') return;
  const st = t.st || effStats(t), tg = ab.pick(t, st, ab, true); if (!tg) return;
  G.delayed.push({ t: .05, fn: () => {
    if (!ccAlive(t)) return; const s = t.st || st, L = ab.pick(t, s, ab, true); if (!L) return;
    ccRecast(t, ab, L, .6, s); t.ccQ = Math.min(t.ccQ || 0, 2);
    part({ k: 'flare', x: t.x, z: t.y, h: towerTop(t) + .2, life: .35, max: .35, size: 1.1, col: CC_COL.arcane });
  } });
}

/* ================= THE CONCLAVE: relics, legendaries, charms and the shop =================
   Registered as the Grove's are (groveitems.js): GEAR_BASES, LEGENDS and SHOP entries with force: 'conclave', and the
   pool FORCES.conclave.items, which applyForce swaps in while the Conclave leads (only its own items drop and stand on
   the shelf). The same rules: one rule you can say in a sentence and see working; drops start at rare (kx 1.6 / 1.35
   keep the old common and uncommon tiers as bigger numbers); no random stats. The Conclave's items lean on mana,
   Arcane Charge, element marks, reactions and ability modifiers more than other forces'. One has a chance on hit (the Mana Moth).
   Relics set st.pw.cc (and their own st.pw key); the Conclave's hooks (forces_conclave_a.js) call the functions below:
   ccItemsOnHit (ccHit), ccItemsAmp (amp), ccItemsKill (kill), ccItemsPulse / ccCharmPulse (pulse), ccItemsTick (tick),
   ccItemsCast (a cast seen), ccItemsLive (live), ccCharmQ (ccCast). Paintings come from forceart_conclave.js. */
function ccPwS(st, k, v) { pwMax(st, k, v); st.pw.cc = 1; }
function ccPwMin(st, k, v) { pwMin(st, k, v); st.pw.cc = 1; }
const ccPendN = k => Math.max(2, Math.round(4 / k));
const ccTomeT = k => Math.max(8, Math.round(15 / k));
const ccMoonT = k => Math.max(18, Math.round(30 / k));
const ccChalkN = k => Math.max(1, Math.round(1.5 * k));
const ccOverN = k => Math.max(8, Math.round(20 / k));
const ccEchoEvery = k => k >= 1.4 ? 3 : 4;
const CC_MANA_COL = '#7ab8ff';
function ccMotes(x, z, h, n, col) { for (let k = 0; k < n; k++) part({ k: 'spark', x: x + R(-.2, .2), z: z + R(-.2, .2), h, vx: 0, vz: 0, vh: R(.5, 1), g: -.2, life: .7, max: .7, size: .04, col }); }

