    fxExplode(z.x, z.z, z.r, 1); fxFire(z.x, z.z, .3, 2); fxRing(z.x, z.z, z.r, '#ff9a3a'); ihAleSplash(z.x, z.z, .3, 16); G.shake = Math.max(G.shake, .2); sfx('boom', 1);
