  if (!tg.dead) chill(tg, { slow: C.so_stagger ? .5 : .4, slowT: C.so_stagger ? 1.2 : .8 }, null, t);
  if (p.so_bossshield && !tg.dead) { stun(tg, .3, .4, null); soEv('item:so_bossshield'); }   // the Bossed Tower-Shield
  if (p.so_lionshield && !tg.dead) { tg.soCondT = Math.max(tg.soCondT || 0, G.time + p.so_lionshield); tg.soCondBy = t; soJudge(tg, 1, t); relicGlint(t, 'so_lionshield'); soEv('item:so_lionshield'); }   // the Aegis of the Lion
