  mat(g, 'barding', () => { for (let i = 0; i < NZ; i++) for (let j = 0; j < NA; j++) {
    const spine = j === NA / 2 - 1 || j === NA / 2, c = spine ? capB : (j + i) % 2 && tier >= 1 ? cap : (j % 2 ? cap : dk(WE.cap, .9));
    huQuad(g, P[i][j], P[i][j + 1], P[i + 1][j + 1], P[i + 1][j], c, ref); huQuad(g, P[i][j], P[i][j + 1], P[i + 1][j + 1], P[i + 1][j], capD, ref, true); } });
  // the ends: the chest and the croup panels, falling from the last arc to the hem
