          G.projs.push({ k: 'arrow', x: t.x, z: t.y, h: towerTop(t) + .05, tg: c, st: Object.assign({}, s, { armorPen: 1 }), src: t, lx: c.x, lz: c.y, lh: hitH(c), spd: 19, pow: m, crit: false, lv: 4, soBolt: 1, soHeavy: 1, abil: 1, big: 1 });
          rfx({ k: 'streak', x0: t.x, h0: towerTop(t), z0: t.y, c, col: SO.COL.light, w: .05, trav: .14, life: .3 });
          part({ k: 'flare', x: t.x, z: t.y, h: towerTop(t), life: .25, max: .25, size: 1, col: SO.COL.silver }); sfx('so_sanct');
