        soLater(t, .3, s => {
          abAoe(() => inSplash(p.x, p.y, ab.rr, false, c => { if (c.phased || c.ent || !canTarget(t, s, c)) return; soAbHit(t, s, c, .6, 'magic'); if (c.dead) return; soBlind(c, d, t); soJudge(c, 1, t); }));
          part({ k: 'flare', x: p.x, z: p.y, h: 1.2, life: .45, max: .45, size: 2.4, col: '#ffffff' }); fxRing(p.x, p.y, ab.rr, SO.COL.blind); flashLight(p.x, p.y, 1.4, [2.2, 2.1, 1.7], 3, .35); sfx('so_flare');
        });
