  so_s_chalk: { tier: 1, cost: 360, name: 'Judgement Chalk', icon: 'rune', hue: '#e8e0c8', text: () => 'Every second strike lays a Judgement on its foe.', fx: st => soPwMin(st, 'so_chalk', 2) },
