Object.defineProperty(SB_STORM, 'dmg', { get() { return typeof G !== 'undefined' && G && G.sb ? G.sb.wDmg || 0 : 0; }, set(v) { if (typeof G !== 'undefined' && G && G.sb) G.sb.wDmg = v; } });
