function sbSurge(src) { const S = sbS(); const to = Math.min(100, (Math.floor(S.storm / 25 + 1e-6) + 1) * 25); if (to > S.storm) { if (src && src.id) S.feedBy[src.id] = (S.feedBy[src.id] || 0) + to - S.storm; S.storm = to; } }

