for (const k in SB_TALENTS) {
  const L = SB_TALENTS[k].list;
  L.forEach((t, i) => t.id = i);
  for (const t of L) if (t.req) { const q = L.find(o => o.r === t.req[0] && o.c === t.req[1]); if (!q || q.c !== t.c || q.r !== t.r - 1) console.warn('SB_TALENTS: bad req', k, t.name); }
}
