          if (c.dead || !abLive(t)) return; const s = t.st || st; t.sbBear.x = c.x; t.sbBear.z = c.y; t.sbBear.hitAt = G.time;
          sbHit(t, s, c, s.dmg * 1.5 * (c.sbHexT > G.time ? 1.5 : 1) * SB_HERO_K(), 'phys', null); c.sbSpiritT = G.time + .6;
          if (k === 2 && !c.dead) { stun(c, byT(ab.by.stun, t), .4, null); G.shake = Math.max(G.shake, .1); }
