/* ---------- the Moonhowl Pelt's wolf hunts on its own clock (sbRelicTick runs it: this is the rule) ---------- */
function sbMoonhowl(t, st, dt) {
  const p = st.pw; if (!p || !p.sbMoonhowl) return;
  if ((t.sbMhT = (t.sbMhT == null ? .5 : t.sbMhT) - dt) > 0) return;
  const c = G.creeps.filter(o => !o.dead && !o.phased && !o.ent && sbWalks(o) && canTarget(t, st, o) && Math.hypot(o.x - t.x, o.y - t.y) <= 2.5).sort((a, b) => a.remain - b.remain)[0];
  if (!c) { t.sbMhT = .25; return; }
  t.sbMhT = p.sbMoonhowl;
  tagged('relic', () => sbWolfLunge(t, st, null, 1, 'a', { c, m: .8, stun: .3, r: 9, T: .5 }));
  relicGlint(t, 'sbl_moonhowl');
}

