function sbLeaf2(g, p, dir, l, w, col) { leaf(g, p, dir, l, w, col); const up = Math.abs(dir[1]) > .9 ? [1, 0, 0] : [0, 1, 0], sx = dir[1] * up[2] - dir[2] * up[1], sy = dir[2] * up[0] - dir[0] * up[2], sz = dir[0] * up[1] - dir[1] * up[0], sl = Math.hypot(sx, sy, sz) || 1, s0 = [sx / sl * w, sy / sl * w, sz / sl * w], m = [p[0] + dir[0] * l * .45, p[1] + dir[1] * l * .45, p[2] + dir[2] * l * .45], tip = [p[0] + dir[0] * l, p[1] + dir[1] * l, p[2] + dir[2] * l]; g.tri(p, tip, [m[0] + s0[0], m[1] + s0[1], m[2] + s0[2]], col); g.tri(p, [m[0] - s0[0], m[1] - s0[1], m[2] - s0[2]], tip, col); }
