  for (let k = 0; k <= n; k++) { const th = k / n * turns * TAU, rr = r * (.08 + .92 * k / n); pts.push([c[0] + (u[0] * Math.cos(th) + v[0] * Math.sin(th)) * rr, c[1] + (u[1] * Math.cos(th) + v[1] * Math.sin(th)) * rr, c[2] + (u[2] * Math.cos(th) + v[2] * Math.sin(th)) * rr]); }
