    if (!F) for (let k = 0; k < 5; k++) { const x = -.06 + k * .03; huTube(g, [[x, hy + .05, -.06], [x * 1.3, hy - .1, -.11], [x * 1.5, hy - .28, -.14]], [.02, .018, .009], P.hair, 5); }   // (with a sculpted head the fall of hair is one sheet: no locks over it)
