const sbP = (base, k, build, pose) => Object.assign(sbPiv(base), { k, build(g, tier) { g.with(T(0, 0, 0, 0, 0, 0, sbS3(tier)), () => build(g, tier)); }, pose(t) { SB_PT = Math.min(t.tier | 0, 2); const q = pose(t, sbAnim(t)); if (!q) return null; const s = sbS3(SB_PT); return [q[0], q[1], q[2], (q[3] || 0) * s, (q[4] || 0) * s, (q[5] || 0) * s]; } });
const SB_SH = .64;
