      if (a && a.id === 'sb_crosswind') { const k = sbPop(a.u, .15, .85); return [-.9 * k, Math.sin(a.u * TAU * 1.5) * 1.1 * k, .5 * k, 0, .05 * k, 0]; }
      if (a && a.id === 'sb_skyshot') { const k = sbPop(a.u, .2, .65); return [-1.15 * k, 0, 0, 0, .04 * k, -.2 * k]; }
