  g.sphere(0, 0, 0, .07, .06, .16, 8, 6, c); g.sphere(0, .03, .15, .05, .05, .055, 7, 5, c); g.with(T(0, .02, .2, 0, Math.PI / 2), () => g.cyl(0, 0, 0, .02, 0, .06, 5, '#fff0c0'));
  for (let k = 0; k < 5; k++) { const a = (k - 2) * .25; sbLeaf2(g, [0, 0, -.12], [Math.sin(a), 0, -Math.cos(a)], .16, .03, k % 2 ? c : d); }   // the tail fan
