// Stormward Lancers: a lance thrust at the walker in reach, then lightning on to 2 (3) more foes; a storm rune under the first
FORCE_ATTACK.wbLance = (t, st, tg, pow) => {
  const [ux, uz] = wbDir(t, tg), x0 = tg.x, z0 = tg.y;
  wbHit(t, st, tg, st.dmg * pow * .6, 'phys', [ux * .08, uz * .08]);
  const o = tg.dead ? nearest(x0, z0, 2, 1, null, q => !q.phased)[0] : tg;
  if (o) wbChain(t, st, o, pow * .4, { from: [x0, hitH(tg), z0] });
  wbRune(t, st, x0, z0, 'storm');
  t.recoil = 1; sfx('zap', .5);
};
// Anvil Guard: the shield slammed down on every walker in reach; every 3rd slam a quake runs 2.5 cells along the road both ways
FORCE_ATTACK.wbSlam = (t, st, tg, pow) => {
  const n = t.wbN = (t.wbN || 0) + 1, r = st.range;
  inSplash(t.x, t.y, r, true, (c, d) => { if (c.ent || c.phased || !canTarget(t, st, c)) return; wbHit(t, st, c, st.dmg * pow * (1 - .3 * d / r), 'phys'); });
  for (const c of G.creeps) if (!c.dead && c.burT > 0 && Math.hypot(c.x - t.x, c.y - t.y) <= r) burrowUp(c, true);
  if (n % 3 === 0) wbQuake(t, st, tg.x, tg.y, 2.5, .6);
  if (G.state === 'play') { fxRing(t.x, t.y, r, '#d8a868'); fxDust(t.x, t.y, 5); G.shake = Math.max(G.shake, .05); }
  t.recoil = 1; sfx('quake', .45);
};
/* a quake along the road from (x, z) both ways for `len` cells (mult × st.dmg to each walker it passes, staggered 0.3 s,
   stone runes every cell); o: { runes (false: none), stun } */
function wbQuake(t, st, x, z, len, mult, o = {}) {
  const P = wbRoad(), i0 = wbRoadCell(x, z)[2]; if (i0 < 0) return;
  for (const dir of [-1, 1]) wbFly({ k: 'quake', t, st, i: i0, dir, left: len, mult, x: P[i0][0], z: P[i0][1], acc: 0, runes: o.runes !== false, stunT: o.stun || .3 });
}
function wbQuakeStep(p, dt) {
  const P = wbRoad(), st = (p.t && p.t.st) || p.st; p.acc += dt * 6;
  while (p.acc >= 1 && !p.done) {
    p.acc -= 1; p.i += p.dir; p.left -= 1;
    if (p.i < 0 || p.i >= P.length || p.left < 0) { p.done = true; break; }
    p.x = P[p.i][0]; p.z = P[p.i][1];
    inSplash(p.x, p.z, .55, true, c => { if (c.dead || c.ent || p.hit.has(c)) return; p.hit.add(c); wbHit(p.t, st, c, ((st && st.dmg) || 0) * p.mult, 'phys'); if (!c.dead) stun(c, p.stunT, .4, 'earth'); });
    if (p.runes && st) wbRune(p.t, st, p.x, p.z, 'stone');
    if (G.state === 'play') { fxDust(p.x, p.z, 3); part({ k: 'ring', x: p.x, z: p.z, h: .04, life: .35, max: .35, size: .5, col: WB_COL.stone }); }
  }
}
// Siege Wardens: a bolt at the walker furthest along: it pins it (root 0.5 s) and blasts the walkers round it; a pin rune
FORCE_ATTACK.wbBolt = (t, st, tg, pow) => {
  const h = towerTop(t) * .7;
  wbFly({ k: 'bolt', t, st, tg, pow, x: t.x, z: t.y, h, x0: t.x, z0: t.y, h0: h, tx: tg.x, tz: tg.y, spd: 9 });
  t.recoil = 1; sfx('ballista', .4);   // (was 'cannon': a crossbow played the cannon)
};
function wbBoltStep(p, dt) {
  const st = (p.t && p.t.st) || p.st;
  if (p.tg && !p.tg.dead) { p.tx = p.tg.x; p.tz = p.tg.y; }
  const th = p.tg && !p.tg.dead ? hitH(p.tg) : .3, dx = p.tx - p.x, dz = p.tz - p.z, dh = th - p.h, D = Math.hypot(dx, dz) || 1e-6, step = p.spd * dt;
  if (D <= step + .05 || p.age > 3) {
    p.done = true;
    const x = p.tx, z = p.tz, tg = p.tg && !p.tg.dead ? p.tg : null;
    if (p.land) { p.land(p, tg); return; }
    if (tg) { wbHit(p.t, st, tg, st.dmg * p.pow, 'phys'); if (!tg.dead) rootFoe(tg, .5, p.t); }
    inSplash(x, z, st.splash || .8, true, c => { if (c !== tg && !c.dead && !c.phased) wbHit(p.t, st, c, st.dmg * p.pow * .5, 'phys'); });
    wbRune(p.t, st, x, z, 'pin');
    if (G.state === 'play') { fxRing(x, z, st.splash || .8, WB_COL.pin); fxDust(x, z, 4); sfx('boltthud'); }
    return;
  }
  p.x += dx / D * step; p.z += dz / D * step; p.h += dh / D * step;
}

/* =====================================================================================================
   THE HOOKS
   ===================================================================================================== */
// the later files add to these: live (t, st), amp (c, src, dot) -> extra, kill (c, src), pulse (t, st, dt), tick (dt), wave (n)
const WB_HOOK = { live: [], amp: [], kill: [], pulse: [], tick: [], wave: [], fire: [] };
FORCE_HOOKS.wardbound = {
  live(t, st) {
    // (Final Oath, wb_laststand: a stoic stand now; its zone stops his strikes, abilities' zone)
    for (const f of WB_HOOK.live) f(t, st);
  },
  amp(c, src, dot) {
    let a = 0;
    // Brands: the Wardbound's spells (and their commanders') bite deeper on a branded foe
    const b = wbBrandOf(c);
    if (b && !dot && ((typeof AB_NOW !== 'undefined' && AB_NOW && src && src.def && src.def.force === WB_ID) || (typeof HERO_SRC !== 'undefined' && src === HERO_SRC))) a += WB_BRAND.per * b;
    for (const f of WB_HOOK.amp) a += f(c, src, dot) || 0;
    return a;
  },
  kill(c, src) { for (const f of WB_HOOK.kill) f(c, src); },
  fire(t, st, tg, pow, echo) { for (const f of WB_HOOK.fire) pow = f(t, st, tg, pow, echo); return pow; },
  impact() {},
  hazard(z, dt) {
    if (z.k === 'wb_rune') { wbRuneTick(z, dt); return true; }
    if (z.k === 'wb_zone') { if (typeof wbZoneTick === 'function') wbZoneTick(z, dt); return true; }
    return false;
  },
  pulse(t, st, dt) {
    // Final Oath and its like: can't be Wounded while it holds (hp kept above 0)
    if (t.wbNoWoundT > G.time && t.maxHp && t.hp < t.maxHp * .05) t.hp = t.maxHp * .05;
    // vow runes: Wardbound units within 1 cell mend 1.5% of their health a second
    if (wbUnit(t) && t.maxHp && t.hp < t.maxHp && !t.wrecked && (t.wbVowChk = (t.wbVowChk || 0) - dt) <= 0) {
      t.wbVowChk = .25;
      if (wbRunes().some(z => z.kinds.includes('vow') && Math.hypot(z.x - t.x, z.z - t.y) <= 1)) wbMend(t, t.maxHp * .015 * .25);
    }
    for (const f of WB_HOOK.pulse) f(t, st, dt);
  },
  tick(dt) { if (G.state !== 'play') return; wbFlightsTick(dt); wbLinesTick(); for (const f of WB_HOOK.tick) f(dt); },
  wave(n) { const S = wbS(); S.linesAt = -1; for (const f of WB_HOOK.wave) f(n); },
};
// mend a unit (Vowkeepers, vow runes, items): a Wounded unit healed to full stands up whole again
function wbMend(t, amt) {
  if (!t || t.wrecked || !t.maxHp || !(amt > 0)) return 0;
  const was = t.hp; t.hp = Math.min(t.maxHp, t.hp + amt);
  if (t.wounded && t.hp >= t.maxHp) t.wounded = false;
  if (t.hp > was && G.state === 'play' && Math.random() < .3) part({ k: 'spark', x: t.x + R(-.15, .15), z: t.y + R(-.15, .15), h: towerTop(t) * R(.4, .9), vh: R(.3, .7), drag: 1, life: .5, max: .5, size: R(.04, .07), col: WB_COL.vow });
  return t.hp - was;
}
// a compact read of the run's runes for the bot and the playlog
function wbStats() { const S = wbS(), R0 = wbRunes(); return { runes: R0.length, bound: R0.filter(z => z.bound).length, lines: wbLinesNow().length, woven: wbLinesNow().filter(l => l.woven).length, n: Object.assign({}, S.n) }; }

/* ================= THE WARDBOUND: talent trees =================
   One tree per unit slot, in the runtime TALENTS shape (GT in forces.js), swapped in by applyForce('wardbound'); the
   Vowkeepers' tree rides the specialist's slot (SPEC_SLOT, 'venom'), the Champions' trees are in
   forces_zx_champ_wardbound.js, and the Oathstones (the wall) have none, as no force's wall does. The usual rules: rows
   open at 0/3/6/9 points in the tree, req [r, c] needs the talent straight above at full rank, the last row's capstones
   are one-of, no drawbacks and no random procs (every trigger is "every Nth", "the first", a state or a clock). The
   shared themes: the runes each unit lays, the ward-lines they link into, Bound runes, brands and sigils.
   Generic mod keys (range, rangeM, airR, armorPen, splash, slow, chain, gHaste) are folded by talentStats; spells are
   shaped through sp (forces_zy_spells.js), with three conditions and three riders of the force's own (registered below,
   once forces_zy_spells.js has loaded: SP_COND wbBrand / wbSig / wbRune, SP_RIDE wbBrand / wbSigil / wbRune). Every cap
   (prefixed wb) is read in this file: through WB_HOOK, WB_RUNE_HOOK, WB_LINE_HOOK and wraps of the strikes and the
   core's helpers (each keeps the original and calls it). */
