  mat(g, 'gilt', () => { for (const yy of [-.44, -.06, .06, y - .14]) huTube(g, [[0, yy - .015, 0], [0, yy + .015, 0]], .021, P.trim, 6); g.with(T(0, y, 0), () => g.cyl(0, 0, 0, .022, 0, .17 + .02 * tier, 6, P.plateL)); });
  const w = .18 + .015 * tier;
  g.em = .3; wbSlab(g, [[.015, y - .01], [.08, y + .05], [w, y + .08], [w + .02, y - .05], [w - .01, y - .18], [.08, y - .17], [.015, y - .11]], .008, P.ice, '#e8f6ff'); g.em = 0;
