const specCaster = c => !!c && !c.dead && c.mpMax > 0;
// a foe that heals or shields others (a healer), or any support foe
const SPEC_HEALS = { pulse: 1, mend: 1, shield: 1, bulwark: 1, revive: 1 };
const specHealer = c => !!c && !c.dead && ((c.epRot && c.epRot.some(e => SPEC_HEALS[e.s])) || !!c.def.heal || !!(c.def.link && (c.def.link.kind === 'heal' || c.def.link.kind === 'ward')));
const specSupport = c => !!c && !c.dead && (isRole(c, 'support') || specHealer(c));
