// the shared foe statuses' icons (buffs.js)
SPEC_BUFF.push(['sx_hushed', { name: 'Silenced caster', kw: 'sx:hushed', kind: 'debuff', pri: 4, icon: 'scales', hue: '#4a6aa8', f: ['hushT'],
  def: 'It casts nothing, a spell it was winding up broke, and its ties to its allies are down.',
  get: c => c.hushT > bfNow() ? { t: bfLeft(c.hushT), src: c.hushBy, say: 'No spells and no ties until it ends.' } : null }]);
