// every cast feeds the Storm and channels through totems, as the Stormborn's own kits do (forces_stormborn_c.js)
for (const h of ['sb_caller', 'sb_wind', 'sb_beast']) for (const ab of CHAMPS[h].kit.abilities) {
  const f = ab.cast; ab.cast = function (t, st, tg, a) { const r = f.call(this, t, st, tg, a || ab); if (r !== false) sbOnCast(t, a || ab, st); return r; };
}

