const wbchRobeR = (y0, rb, y) => { const v = Math.max(0, Math.min(1, (y0 - .01 - y) / (y0 - .04))), r = v < .2 ? .105 + (.132 - .105) * Math.sin(v / .2 * Math.PI / 2) : .132 + (rb - .132) * Math.pow((v - .2) / .8, 1.2); return r * (1 + .075 * Math.pow(v, 1.2)) + .002; };
