const gvcWalker = c => !c.dead && !c.ent && !c.phased && abWalker(c);
const gvcTop = t => (typeof towerTop === 'function' ? towerTop(t) : 1);
// Growth (forces_zz_growth.js): a spell that feeds the gauge
