// a held foe for bosses: the deep roots bite through part of the usual cut (rootFoe gives bosses 0.45)
const gvcRootBig = (c, d, t, keep) => rootFoe(c, c.def.boss ? d * keep / .45 : d, t);

/* ---------- the road: where the path runs near a unit ---------- */
const gvcPts = () => (G.path && G.path.pts) || [];
function gvcPathIdx(x, z) { const P = gvcPts(); let b = -1, bd = 1e9; for (let i = 1; i < P.length - 1; i++) { const d = (P[i][0] - x) ** 2 + (P[i][1] - z) ** 2; if (d < bd) { bd = d; b = i; } } return b; }
