  for (let i = 2; i < P.length - 1; i++) { const d = (P[i][0] - t.x) ** 2 + (P[i][1] - t.y) ** 2; if (d <= bd) { bd = d; b = i; } }
  if (b < 0) return null;
  const a = P[Math.max(1, b - 1)], c = P[Math.min(P.length - 1, b + 1)], l = Math.hypot(c[0] - a[0], c[1] - a[1]) || 1;
  return { x: P[b][0], y: P[b][1], i: b, tx: (c[0] - a[0]) / l, tz: (c[1] - a[1]) / l };
