    if (n) { const mx = sx / n - z.x, mz = sz / n - z.z, l = Math.hypot(mx, mz), s = Math.min(l, .25); if (l > 1e-3) { z.x += mx / l * s; z.z += mz / l * s; z.tx = z.x; z.tz = z.z; } }
