  GVC_K = { bark: vfxC('#fff2e2', 1.2), dead: vfxC('#9a8c7c'), soil: vfxC('#3a2a18'), thornB: vfxC('#3a2214'), thornT: vfxC('#ecf0b0'), glow: vfxC('#62d83a'), sap: vfxC('#a6ff5a', 1.4), tip: vfxC('#f4ffc8', 1.5),
    leaf: vfxC('#e8ffd0'), pod: vfxC('#5a9a30'), moon: vfxC('#bfe2ff', 1.2), moonHot: vfxC('#f0f8ff', 1.5), spore: vfxC('#c8d860'), sporeHot: vfxC('#f4f8b0', 1.3), cap: vfxC('#e8c878'), capD: vfxC('#a8784a'), stem: vfxC('#f0e4c8'),
    petal: vfxC('#ff8a7a'), petalL: vfxC('#ffd0c0'), maw: vfxC('#ffb060', 1.3), moth: vfxC('#fff0b8', 1.2), mothW: vfxC('#f4e0a0'), wither: vfxC('#7a8a5a'), witherHot: vfxC('#c8d0a0', 1.1), witherDark: vfxC('#2a4a24'), pink: vfxC('#ff6a8a'), white: vfxC('#ffffff', 1.3), gold: vfxC('#ffe08a', 1.3) };
