      if (!vfxLite()) { vfxFlat(VX, c.x, c.z, .035, .2 * S, .2 * S, 0, K.spore, .3 * al * (.7 + .3 * Math.sin(now * 3 + c.z)), VT.GLOW, 1); for (let k = 0; k < 3; k++) vfxSprite(VX, c.x + Math.cos(k * 2.1 + c.x) * hc * .5, hS + .06, c.z + Math.sin(k * 2.1 + c.x) * hc * .3, .02 * S, .02 * S, 0, K.sporeHot, .8 * al, VT.GLOW, 1); }
