    for (let k = 0; k < 4; k++) { const sd = k < 2 ? 1 : -1, w = (k % 2 ? .05 : -.05) * S; vfxThorn(VX, hx + w, hh + sd * .05 * S * open, hz, 0, sd * .6, 0, 0, -sd * .8, 0, .1 * S, .03 * px, K.thornB, K.thornT, K.glow, al, .2, 1); }
