    const alive = q.t && q.t.ab && q.t.ab.zones.includes(z);
    if (!alive) { if (q.end == null) q.end = q.age; } const fe = q.end == null ? 1 : Math.max(0, 1 - (q.age - q.end) / .45); if (fe <= 0) { q.life = 0; return; }
    if (q.cx == null) { q.cx = z.x; q.cz = z.z; }
