      const ph = q.seed + k * 2.39996, rr = r * (.25 + .7 * ((k * .618) % 1)), sp = (.8 + .5 * ((k * .29) % 1)) * (k % 2 ? 1 : -1);
      const a = ph + q.age * sp, hb = .2 + .32 * ((k * .41) % 1) + .06 * Math.sin(q.age * 3 + ph);
      let x = q.cx + Math.cos(a) * rr, h = hb, zz = q.cz + Math.sin(a) * rr * .85;
