      if (f < 1) { const e = f * f * (3 - 2 * f); x = q.o[0] + (x - q.o[0]) * e; zz = q.o[2] + (zz - q.o[2]) * e; h = q.o[1] + (h - q.o[1]) * e + Math.sin(Math.PI * e) * .15; }
      // a moth: two pale wings (the feather card, near white) beating about a small glowing body, big enough to read
