      const fp = .35 + .65 * Math.abs(Math.sin(q.age * 18 + ph)), s = .16 * Math.max(.85, q.S), al = fe, ro = Math.sin(q.age * 2 + ph) * .3;
      vfxSprite(VX, x, h, zz, s * 1.3, s * 1.3, 0, K.moth, .16 * al, VT.GLOW, 1);   // (a soft glow, not a flash)
