/* ---- Elowen's walking tree and her Rootway, drawn with her (CHAMPS.rootmother.extra) ---- */
if (typeof CHAMPS !== 'undefined' && CHAMPS.rootmother) CHAMPS.rootmother.extra = function (t, tier, x, z, yaw, K) {
  if (!t.ab || inIcon) return;
  for (const zn of t.ab.zones) {
    const left = zn.until - G.time; if (left <= 0) continue;
    if (zn.k === 'ch_oldwood') {
      const age = G.time - zn.at, s = Math.min(1, age * 2.5, left * 2) * 1.55, walk = !(zn.wait > 0), st = walk ? Math.sin(age * 7) : 0, ry = Math.atan2(-(zn.hx || 0), -(zn.hz || 1));
      M4.trs(CH_M, zn.x, Math.abs(st) * .04 * s, zn.z, ry, .05 * Math.abs(st), .07 * st, s, s * (1 + .03 * Math.cos(age * 14)), s);
      item(dynMesh('ch_sapling', chSapling), CH_M, {});
      QG.ground(zn.x, zn.z, .02, .55 * s, .55 * s, [.45, .9, .3, .2 * Math.min(1, left)], 5, 0);
    }
    if (zn.k === 'ch_rootway') for (const p of chPathNear(t.x, t.y, zn.r)) QG.ground(p[0], p[1], .02, .32, .32, [.4, .85, .3, .16 * Math.min(1, left)], 5, 0);
  }
};

