      if (!sbcOn() && G.bolts.length < 60) G.bolts.push({ pts: [[P.x, 4.4, P.z], [P.x + R(-.1, .1), 2.2, P.z], [P.x, 1, P.z]], life: .26, max: .26, w: 2, col: [.75, .88, 1.4] });
