/* =====================================================================================================
   SPIRIT WALKERS: masked walkers between worlds. Fantasy: the ancestors remember every wound, and they collect.
   ===================================================================================================== */
sbcSet('sb_reckoning', { name: "Ancestors' Toll", short: 'Toll', glyph: 'scales', hue: '#e0d8ff', mana: 75, cd: 9, pref: 'high',
  by: { mult: [1.5, 1.5, 1.75, 1.75, 2, 2] },
  auto: 'two or more hexed foes in reach holding something (or one hexed boss or elite)',
  text: (t, st, ab) => `Tears the stored debt out of every hexed foe in reach, ×${byT(ab.by.mult, t)}, and strikes the toughest foe with all of it. The foes it is torn from are slowed 30% for 1.5s.`,
  pick(t, st, ab, man) {
    const A = abFoes(t, st, abReach(t, st, ab)), L = A.filter(c => c.sbHexT > G.time && (man || sbHexHeld(c) > abD(st) * .5));
    if (!L.length || !(L.length >= (man ? 1 : 2) || L.some(abBig))) return null;
    const c = abToughest(A); return c ? { x: c.x, y: c.y, c, L } : null;
  },
  cast(t, st, p, ab) {
    const m = byT(ab.by.mult, t), cap = Math.max(1, abD(st) * 10), mem = st.caps && st.caps.sbMemory ? 2 : 1; let tg = p.c, i = 0;
    for (const d of p.L) {
      if (d.dead || !(d.sbHexT > G.time)) continue;
      const amt = Math.min(cap, sbHexHeld(d) * m * mem); d.sbHexHp = d.hp; d.sbHexStore = 0;
      if (d !== tg) chill(d, { slow: .3, slowT: 1.5 }, null, t);
      if (!(amt > .5)) continue;
      const from = d, k = i++;
      sbcFx('sb_reckoning', t, from, C => { const K = sbcK(); v2Beam(C, from.x, hitH(from), from.y, tg.x, hitH(tg) + .2, tg.y, { delay: .04 * k, w: .07, life: .45, grow: .22, col: K.spirit, ccol: K.spiritH, wob: .1, sag: -.3, foe: tg, tube: 0 }); v2Spray(C, 'wisp', from.x, from.y, hitH(from), 3, { sp: .5, col: '#cfc0ff' }); });
      G.delayed.push({ t: .26 + .06 * k, fn: () => {
        let to = tg; if (!to || to.dead) { const s = t.st || st; to = tg = abToughest(abFoes(t, s, abReach(t, s, ab))); } if (!to || !abLive(t)) return;
        hurt(to, amt, 'pure', t, true, null, null);
        part({ k: 'flare', x: to.x, z: to.y, h: hitH(to), life: .25, max: .25, size: .8, col: '#d8c8ff' });
      } });
    }
    sfx('ward', 1); sfx('curse', 0);
    G.delayed.push({ t: .32 + .06 * i, fn: () => { const to = tg; if (!to || to.dead || !abLive(t)) return; sbcFx('sb_reckoning', t, to, C => { v2Mark(C, to, { L: VT.GLYPH, s: .3, life: .8, spin: 2 }); v2Hit(C, to.x, to.y, hitH(to), 1, { sp: 'wisp', n: 8, sp2: 'feather', n2: 3, shake: .05 }); }); sfx('arcane', 1); } });
  },
});
SBC_CAST.sb_reckoning = C => { const t = C.t; v2Wind(C, { wu: .16, n: 7, rel: 'wisp', reln: 3 }); };

