    for (const o of G.towers) if (o.def && o.def.unit === 'sb_wolfguard' && !o.wrecked && from.length < n + 4 && Math.hypot(o.x - c.x, o.y - c.y) <= 6) { o.sbWolf = { c, x: c.x, z: c.y, at: now, T: 1.1, big: true }; from.push({ wg: o, at: now }); }
    for (const f of from) if (!f.wg) runs.push({ x0: f.x, z0: f.z, c, at: f.at, T: .6 });
