  rider: { wl: -.03, ws: .01, hl: .075, hs: -.02, br: .008, rate: 1.5, cast: .7 },
  throw: { wl: -.045, ws: -.01, hl: .07, hs: -.02, br: .011, rate: 1.7, cast: 1 },
  gun: { wl: .015, ws: -.01, kick: .085, ks: -.02, br: .01, rate: 1.6, cast: .8 },
