const socShields = (t, r) => G.towers.filter(o => o !== t && o.def && o.def.unit === 'templar' && !o.wrecked && !(o.build > .5) && Math.hypot(o.x - t.x, o.y - t.y) <= (r || SOC_SHIELD_R));
