      if (k > 0) tg = nearest(lx, lz, 2, 8, null, q => socFoe(q) && abWalker(q) && !struck.has(q) && canTarget(t, s, q)).reduce((b, q) => !b || soJ(q) > soJ(b) || (soJ(q) === soJ(b) && abByTough(q, b) < 0) ? q : b, null);
      if (!tg || tg.dead) return; const o = tg; struck.add(o);
      const [ux, uz] = abDir(t, o), L = Math.max(0, abDist(t, o) - .4); t.ang = Math.atan2(o.x - t.x, o.y - t.y); t.chg = { x: t.x + ux * L, z: t.y + uz * L, at: G.time, T: P * .95 };
      const fx0 = lx, fz0 = lz; lx = o.x; lz = o.y;
