    socFx('ch_highnoon', t, null, C => { for (const c of G.creeps) if (socFoe(c) && soBlinded(c) && inRange(t, st, c)) sfxAdd({ k: 'vflash', x: c.x, z: c.y, h: hitH(c), s: .3, life: .15, col: socC(C, SOC.white), a: .35 }); });
