  pick(t, st, ab, man) { const L = ihPick(t, st, abReach(t, st, ab)), k = abCrowd(L, IHC_UN.r); return k && (k.n >= (man ? 1 : 3) || abBig(k.c) || L.some(c => c.ihBrandT > G.time && (c.x - k.c.x) ** 2 + (c.y - k.c.y) ** 2 < 1.44)) ? { x: k.c.x, y: k.c.y } : null; },
