          ihcFx(ab.id, t, c, C => { sfxAdd({ k: 'vring', x, z, r0: .1, r1: IHC_GP.crashR * C.T.ring, life: .4 * C.T.dur, col: ihcC('#c8b8a0'), rot: R(TAU) }); v2Spray(C, 'dust', x, z, .1, 8, { r: .3, sp: .9 }); v2Spray(C, 'rock', x, z, .1, 5, { sp: .8 }); sfxAdd({ k: 'vflash', x, z, h: .2, s: .5 * C.T.glow, life: .12 * C.T.dur, col: ihcC('#e8d8b0'), a: .4 * sfxZk() }); });
