    G.delayed.push({ t: .3, fn: () => { if (!abLive(t)) return; t.ang = Math.atan2(x - t.x, z - t.y); const mz = ihMuzzle(t); ihcFx(ab.id, t, p, C => { const m = sfxMuzzle(t) || [mz[0], mz[1], mz[2], 0, 1]; v2Muzzle(C, m[0], m[2], m[1], m[3], m[4], .9); v2Proj(C, m[0], m[1], m[2], x, IHC_SS.h, z, trav - .3, { arc: .4, head: 5, s: .07, col: ihcC('#ffe8b0'), hot: ihcC('#ffffff', 1.4), tw: .05 }); }); sfx('cannon', 2); } });
