        lit.add(p); p.fire = true; p.until = Math.max(p.until, G.time + 3);
        abAoe(() => inSplash(p.x, p.z, p.r + .1, true, o => { if (canTarget(t, s, o)) abHit(t, s, o, IHC_FB.flash, 'magic'); }));
        ihcFx(ab.id, t, null, C => { v2Flames(C, p.x, p.z, p.r, 8, { mode: 1, life: .8, s: .2 }); sfxAdd({ k: 'vflash', x: p.x, z: p.z, h: .2, s: .5 * C.T.glow, life: .14 * C.T.dur, col: ihcC('#ff8a3a'), a: .5 * sfxZk() }); });
        sfx('fireHit', 0);
