  if (k === 0) v2Wedge(C, t.x, t.y, ux, uz, IHC_FB.r, half, { col: ihcC('#ff6a1a'), hot: ihcC('#ffd070', 1.3), al: .3, sweep: .14, life: .25 + IHC_FB.gap * 3 });
  const n = sfxN(ihcLite() ? 6 : 14);
