  pick(t, st, ab, man) { const L = abFoes(t, st, abReach(t, st, ab), abWalker), k = abCrowd(L, IHC_LO.r); return k && (k.n >= (man ? 1 : 3) || abBig(k.c)) ? { x: k.c.x, y: k.c.y } : null; },
