        for (const q of (t.chPud || [])) { q.fire = true; q.until = Math.max(q.until, G.time + 3); }
        if (typeof chPuddle === 'function') { chPuddle(t, x, z, true); const P2 = t.chPud; if (P2 && P2.length) P2[P2.length - 1].r = r; }
        ihcFx(ab.id, t, p, C => { v2Flames(C, x, z, r, 16, { mode: 1, life: 1.2, s: .3 }); sfxAdd({ k: 'vflash', x, z, h: .3, s: r * 1.1 * C.T.glow, life: .2 * C.T.dur, col: ihcC('#ff8a3a'), a: .4 * sfxZk() }); sfxAdd({ k: 'vburst', x, z, h: .25, s: r * .8 * C.T.glow, life: .45 * C.T.dur, col: ihcC('#ff6a1a'), hot: ihcC('#ffd070', 1.5), a: .6 * sfxZk(), rot: R(TAU) }); v3P(C, 'fire', x, .05, z, 10, { r: r * .8 }); v2Spray(C, 'ember', x, z, .2, 14, { r: r * .8, sp: .8 }); flashLight(x, z, .5, C.P.light, 3, .35); for (const q of (t.chPud || [])) if (q.x !== x) v2Flames(C, q.x, q.z, q.r, 8, { mode: 1, life: .9, s: .2 }); });
        G.shake = Math.max(G.shake, .15); sfx('boom', .8); sfx('fire', 1);
