  if (by) Object.defineProperty(A, 'by', { value: Object.assign({}, ab.by, by) });
  let r = false;
  abRun(ab.id, () => { r = ab.cast.call(ab, t, t.st || st, tg, A); });
  part({ k: 'flare', x: t.x, z: t.y, h: towerTop(t) + .15, life: .2, max: .2, size: .35, col: ab.hue || '#d8ecff' });
  return r;
