  SFX_V2.so_bash = vHit({ wind: { wu: .07, L: -1, hk: .6, off: .4 }, s: 1, hit: { sp: 'spark', n: 8, sp2: 'gold', n2: 4, shake: .06 },
    fx: (C, x, z, h, ux, uz) => { v2Slash(C, x, z, h, ux, uz, .62 * C.S, { life: .22 }); sfxAdd({ k: 'vring', delay: .05, x, z, r0: .2, r1: .65 * C.S, life: .3, col: v2K(C).a, rot: R(TAU) }); } });
  // Aegis: a sunburst opens under the guard, a dome of gold light swells to its reach, a ring of light rises up every ally in it
  SFX_V2.so_aegis = vBuff({ r: 1.6, wind: { wu: .1, r: .7 }, halo: { sp: 'gold', n: 3 },
    fx: (C, x, z, r) => { sfxAdd({ k: 'v2disc', x, z, r, L: VT.SUN, col: v2K(C).a, rim: v2K(C).b, spin: .4, seed: R(TAU), fin: .2, fout: .5, life: 1 * C.T.dur, al: .7, ink: 1, fill: .2 }); sfxAdd({ k: 'vflash', x, z, h: .6, s: r * .9, life: .35 * C.T.dur, col: v2K(C).a, a: .22 * sfxZk() }); } });
  // Rebuke: a shaft of light falls on the knight, then a sunburst blasts out to its reach, gold sparks running to the edge
  SFX_V2.so_rebuke = vArea({ self: 1, wind: { wu: .12, r: .6 }, r: C => (C.ab && C.ab.r) || 1.5,
    cast: C => { if (C.t) v2Shaft(C, C.t.x, C.t.y, { w: .24, fin: .14, life: .55 }); },
    area: { sp: 'gold', n: 8, rim: 'spark', rn: 12, shake: .08 } });
  // Sanctified Bolt: light gathers on the crossbow, the bolt flies on a gold thread, the hit flares in a sunburst under a shaft
  SFX_V2.so_sanct = { cast: C => v2Wind(C, { wu: .32, L: VT.SUN, r: .5, hk: .8, off: .35, n: 9 }), steps: 1,
    hit: C => { const t = C.t, m = t && sfxMuzzle(t); if (t) sfxAdd({ k: 'vflash', x: m[0], z: m[2], h: m[1], s: .4 * C.S, life: .14, col: v2K(C).hot, a: .9 * sfxZk() }); },
    trail: (C, p) => v2Trail(C, p, { w: .11 }),
    land: (C, x, z, h) => { v2Hit(C, x, z, Math.max(.35, h), C.S * 1.05, goldSp); v2Shaft(C, x, z, { w: .14, fin: .08, life: .4, h: 2.6 }); } };
  // Hail of Bolts: a wedge of gold opens over the exact cone, then each bolt flies on a gold thread and sparks where it lands
  SFX_V2.so_hail = { cast: C => v2Wind(C, { wu: .07, L: -1, hk: .8 }), steps: 6, hit: () => {},
    travel: C => { const t = C.t, sp = sfxSpots(C); if (!t || !sp.length) return; let ux = 0, uz = 0; for (const q of sp) { const l = Math.hypot(q[0] - t.x, q[1] - t.y) || 1; ux += (q[0] - t.x) / l; uz += (q[1] - t.y) / l; } const l = Math.hypot(ux, uz) || 1, st = t.st || effStats(t); v2Wedge(C, t.x, t.y, ux / l, uz / l, abReach(t, st, C.ab), Math.PI / 4, { al: .45, life: .55 }); },
    trail: (C, p) => v2Trail(C, p, { w: .07 }),
    land: (C, x, z, h, k) => v2Hit(C, x, z, Math.max(.35, h), C.S * .6, { star: k ? 0 : 1, sp: 'spark', n: 4, light: 0 }) };
  // Witness: a beam from the crossbow fixes a golden eye-sigil over the foe, turning there while it is watched
