        b3 = .8665 * b3 + x * .3104856; b4 = .55 * b4 + x * .5329522; b5 = -.7616 * b5 - x * .016898;
        d[i] = b0 + b1 + b2 + b3 + b4 + b5 + b6 + x * .5362; b6 = x * .115926;
