    e.pre = g(1);
    const ceil = f => { const b = c.createBiquadFilter(); b.type = 'lowpass'; b.frequency.value = f; b.Q.value = .6; return b; };
    const c1 = ceil(CEIL_HZ), c2 = ceil(CEIL_HZ), post = g(1); e.pre.connect(c1); c1.connect(c2); c2.connect(post);
    const b1 = ceil(BRIGHT_HZ), b2 = ceil(BRIGHT_HZ); e.brightPre = g(1); e.brightPre.connect(b1); b1.connect(b2); b2.connect(post);
    if (o.tap === 'pre') post.connect(c.destination);
