    u: [[320, 1], [870, .25], [2240, .07], [3200, .04]], e: [[530, 1], [1840, .45], [2480, .3], [3500, .12]],
    i: [[280, 1], [2250, .32], [3010, .3], [3700, .12]], ae: [[660, 1], [1720, .5], [2410, .3], [3400, .12]],
    uh: [[520, 1], [1190, .45], [2390, .2], [3400, .1]], er: [[490, 1], [1350, .45], [1690, .35], [3300, .1]],
