      thump(t, 150 * (1 - .08 * lv), 85, .06 + .015 * lv, .28 + .05 * lv, { pan });
      nhit(t, { n: 'p', type: 'bandpass', f: rnd(430, 520), q: 1.4, pts: [[.004, 1], [.055, 0]], v: .32, pan });
