      const p = rnd(.92, 1.08) * (1 - .04 * lv) * (1 - .03 * m), L = gl ? .07 : .04;
      if (!gl && recSfx(t, take('gflesh'), { v: .075 * k, pan, raw: 1 })) return;   // recorded: thud and squelch
      nhit(t, { n: 'p', type: 'bandpass', fp: [[0, 2300 * p], [L, 850 * p]], q: 1.3, type2: 'lowpass', f2: 2800, q2: .7, pts: [[.002, 1], [L * .6, .45], [L + .02, 0]], v: .2 * k, pan });
      nhit(t + .004, { n: 'p', type: 'lowpass', f: 900 * p, q: 1.1, pts: [[.004, .9], [.035, .6], [.1, 0]], rough: .9, roughR: .0025, v: .36 * k, pan });
      thump(t, 125 * p, 72, .05, .08 * k, { pan });
