      nhit(t + .32, { type: 'bandpass', f: 1100, q: 4, d: .015, v: .14, room: .2 }); wood(t + .32, 300, .05, .16, { room: .2 });   // the lock
      thump(t + .44, 140, 70, .12, .32, { room: .25 }); nhit(t + .44, { type: 'bandpass', f: 650, q: 2.5, d: .05, v: .18, room: .25 });
      const e = t + .5;   // the school wakes
