    const gg = gn(RKG[i] * .9 * Math.pow(v, 1.4)), lp = bq('lowpass', Math.min(19000, 1500 + p.bright * 18000 * (.35 + .65 * v)), .5);
    let o2 = gg; if (C.createStereoPanner) { const pa = C.createStereoPanner(); pa.pan.value = RKP[i] * p.width; gg.connect(pa); o2 = pa; }
