          if (chance(.55)) A.ans = { at: t + rnd(2.5, 5) + (kind === 'eared' ? 6 : 0), kind: chance(.75) ? kind : 'tawny', pan: -Math.sign(pan || 1) * rnd(.4, .9), far: lim(far + rnd(.1, .3), 0, 1) };
