    // ambience rests)
    if (pref.sfx && !bgTab) try { ambRun(ctx.currentTime + .4); } catch (e) {}
    const M = L.M;
    if (!pref.music) { M.next = Math.max(M.next, ctx.currentTime + .1); reap(); return; }
    M.int = wantInt; M.calm = wantCalm && !wantInt;
