    land = mix(land, uLowC[3], 1. - smoothstep(uLowR.w*.5, uLowR.w, rd));                                // the river
    land *= 1. - uLow.w*smoothstep(.48, .68, fbm(xz*.09 + vec2(uTime*.008, uTime*.005)));               // cloud shadows drifting
