        vfxSprite(VX, p.x + RD.right[0] * off, p.h + Math.abs(sw) * s * .1, p.z + RD.right[2] * off, s, s * .5, p.rot + sw * .6, vfxTint(c, .5), Math.min(1, a * 2), VT.FEATHER, 0, .04);
