        g.with(T(s * .1, .82, .15, 0, -.15, s * -.4), () => { creepBall(g, [0, 0, 0], [.062, .092, .026], furD, { su: 7, sv: 4 }); creepBall(g, [0, -.006, .015], [.04, .064, .012], C.ear, { su: 7, sv: 4 }); });
