        { const P = []; for (let q = 0; q < 10; q++) { const a = q / 10 * TAU; P.push([Math.cos(a) * .132, -.022, Math.sin(a) * .137]); } creepTube(g, P, .017, 3, bronze, { loop: true }); }
        for (const dz of [-.045, .045]) creepTube(g, [[s * .03, .07, dz], [s * .06, .13, dz * 1.1], [s * .09, .19, dz * 1.25]], [.022, .014, 0], 4, C.tusk, { capA: false });
