    const th = ph + s * 6.0 + (fbm2(s * 1.7 + ph, t * .017) - .5) * 3.2 + (fbm2(s * 5.3 + 7, t * .04 + ph) - .5) * .6;
    const rr = r * 1.1 + .55 + (fbm2(s * 2.4 + 3, t * .024 + ph * 2) - .5) * .9 + (fbm2(s * 8.1, t * .06 + 9) - .5) * .2 + s * s * .5;   // (in and out, eddies; drifting out at the top)
