    id: 'mistfall', sunDir: nrm3([-.54, .73, -.42]), sunCol: [1.6, 1.25, .8], sky: [.2, .3, .3], gnd: [.14, .16, .09], fogHex: '#24463e',
    pitch: 57, fitTop: POOL_RECT[1] + .1, fitBot: POOL_RECT[1] + POOL_RECT[3] - .1, noKeep: true, h: () => 0, fly: [.85, 1, .45],
