  QADD.bill(RD, 7.0, 1.5, -7.8, 3, 1.9, [1, .95, .8, .26 * br * k], 1, 0);
  QADD.ground(6.6, -5.9, .04, 2.2, 1.3, [1, .9, .64, .1 * br * k], 1, 0);   // (its light on the road)
