  g.em = 1; for (const s of [-1, 1]) g.with(T(s * .085, .66, .235, s * .35, .5, 0), () => { const c = s < 0 ? ember : iceL; creepRBox(g, [0, 0, 0], [.012, .045, .008], .5, c, { su: 4, sv: 3 }); creepRBox(g, [s * .022, -.01, -.004], [.02, .01, .008], .5, c, { su: 4, sv: 3, r: [0, 0, s * .7] }); }); g.em = 0;
  // black fur mantle; black horn spikes on the ember side, ice shards on the rime side
