    for (const [dx, dz, h, w] of [[.0, .0, .3, .042], [-.07, .05, .22, .034], [-.04, -.07, .24, .034], [.06, -.03, .18, .03], [.04, .07, .16, .028]]) l2Flame(g, [c[0] + dx, c[1] + .055, c[2] + dz], h, w, creepNrm([1, 0, .6]), ember, emberC, [-.35, 0, -.15]);
