  const bands = (l, e, f, col) => { const dd = creepNrm(cSub(f, e)); l.em = 1; for (const t of [.5, .8]) l.with(creepFrame(creepLerp(e, f, t), dd, [1, 0, 0]), () => l2Loop(l, [0, 0, 0], .062 - t * .012, .062 - t * .012, .009, col, 9, 3)); l.em = 0; };
