    for (const [dx, dz, h, lean, r] of [[.1, -.06, .34, .55, .07], [-.04, .1, .22, .1, .06], [.2, .07, .2, 1.0, .05]]) l3Crystal(g, [s * (.44 + dx), 1.22, -.01 + dz], [s * Math.sin(lean) * .9, 1, -.1], h, r, obs, B[1], 0);
