    l.em = .95; creepTube(l, [[s * .045, -.37, .02], [s * .045, -.31, .02]], .115, 8, lavaM, { capA: 'flat', capB: 'flat' }); l.em = 0;
    const fa = l3Rock(l, [s * .055, -.48, .04], [.14, .15, .14], B, 37 + s, F);
