  { const P = []; for (let q = 0; q <= 10; q++) { const t = -1.05 + q / 10 * 2.25; P.push([0, C[1] + Math.cos(t) * R[1] * 1.01, C[2] + Math.sin(t) * R[2] * 1.01]); } creepTube(g, P, .022, 5, '#d8ff70', { capA: true, capB: true }); }
  g.em = 0;
