  creepBall(g, [0, .4, .4], [.17, .13, .13], ch, { su: 10, sv: 6 });
  creepHard(g, () => { for (let k = 0; k < 7; k++) { const t = (k - 3) / 3, b = [t * .16, .5, .32 - Math.abs(t) * .08], h = .34 - Math.abs(t) * .13; L4Spike(g, b, [b[0] * 1.7, b[1] + h, b[2] - .07], .038, chM, gold, .42, 4); } });
  g.em = 1; for (const [x, y, r] of [[-.04, .45, .027], [.04, .45, .027], [-.085, .43, .022], [.085, .43, .022], [-.06, .48, .018], [.06, .48, .018], [-.115, .4, .018], [.115, .4, .018]]) creepBall(g, [x, y, .515 - Math.abs(x) * .4], [r, r, r * .7], eye, { su: 5, sv: 3 }); g.em = 0;
