  hallow: { n: 'The Hallowed Mile', glyph: 'sunburst', t: 'The cursed ground turns: for the rest of the run, foes standing on it take 20% more damage from every unit.' },
  severed: { n: 'Severed Ties', glyph: 'chains', t: 'For the rest of the run, when a support caster falls, every foe it was covering is slowed 40% for 3 seconds.' },
