const QX_HUSH = { every: 12, warn: 3, hold: 5 };

/* ---- an offer ---- */
function qxOpt(id, T, at) {
  const D = QX[id], o = { id, T, at };
  if (D.prep) D.prep(o);
  o.dur = o.dur || D.dur(T, at); o.until = at + o.dur - 1;
  o.kind = D.kind; if (D.kind === 'hold') o.lives = D.lives(T);
  o.reward = D.reward(o);
  {   // every challenge also pays gold on top of its reward (owner, 8 Nov 2026): added to a gold reward it already has
    const add = Math.round(8 * Math.pow(1.3, (at - 8) / 5)) * 10, g = o.reward.find(r => r.k === 'gold');   // 80 at wave 8, 30% more each challenge after (owner: half the first figure, then climbing faster)
    if (g) g.n += add; else o.reward.push({ k: 'gold', n: add });
  }
  for (const r of o.reward) if (r.k === 'relic') {   // three different relics, rolled now so the card can show them
    r.items = []; const key = it => it.base || it.leg || (it.tome || []).join(':');
    for (let k = 0, guard = 0; k < 3 && guard < 40; guard++) { const it = rollGear(Math.max(at, 6), true, r.rar); if (guard < 30 && r.items.some(x => key(x) === key(it))) continue; r.items.push(it); k++; }
  }
  return o;
}
function qxMakeOffer(at, tier) {
  const Q = qxState(), recent = Q.log.slice(-3).map(l => l.id).concat(Q.lastOffer || []);
  const ok = Object.keys(QX).filter(id => tier >= QX[id].tiers[0] && tier <= QX[id].tiers[1]);
  let pool = ok.filter(id => !recent.includes(id) && (!QX[id].can || QX[id].can({ at, T: tier })));
  if (pool.length < 2) pool = ok.filter(id => !QX[id].can || QX[id].can({ at, T: tier }));
  const pick = [];
  while (pick.length < 2 && pool.length) pick.push(pool.splice(Math.floor(Math.random() * pool.length), 1)[0]);
  Q.lastOffer = pick.slice();
  return { at, tier, opts: pick.map(id => qxOpt(id, tier, at)) };
}
function qxTake(i) {
  const Q = qxState(), o = Q.offer && Q.offer.opts[i]; if (!o) return false;
  Q.offer = null;
  Q.cur = Object.assign({}, o, { state: 'on', lost: 0, p: 0, from: o.at });
  if (o.id === 'mile') Q.cur.zone = qxMileZone();
  if (o.id === 'hunter') Q.cur.mark = qxTopUnit();
  if (o.id === 'hush') Q.cur.hushT = QX_HUSH.every;
  qxRefresh();
  onBanner(QX[o.id].n, `${qxSay(Q.cur)} · waves ${o.at}${o.until > o.at ? '–' + o.until : ''}`);
  sfx('horn', 0); onDirty(); onSave(); return true;
}
function qxSkip() { const Q = qxState(); if (!Q.offer) return; Q.log.push({ id: 'skip', at: Q.offer.at }); Q.offer = null; onDirty(); onSave(); }
const qxSay = o => QX[o.id].say ? QX[o.id].say(o) : QX[o.id].n;
// a wave's spec and the caches that read it (the boss rule) go stale when a twist starts or ends
function qxRefresh() { if (typeof _brAt !== 'undefined' && _brAt.clear) _brAt.clear(); if (typeof _fcFirst !== 'undefined') for (const k in _fcFirst) delete _fcFirst[k]; }
const qxLive = id => { const c = G.qx && G.qx.cur; return !!(c && c.state === 'on' && (!id || c.id === id)) ? c : null; };
const qxIn = (c, n) => !!c && n >= c.from && n <= c.until;

/* ---- the twists a wave carries, for the cards and the forecast ---- */
