TOWER_BUILD.arrow = function (g, tier, A, rnd) {
  const P = ARROW_PAL, jit = g.jit, C4 = [[-1, -1], [1, -1], [1, 1], [-1, 1]];
  g.jit = .03;
  // per level: plinth (pw0->pw1, ph), stone stage (s0->s1 up to sy), timber stage (t0->t1), deck half-width, hood
  const L = [
    { ph: .1, pw0: .46, pw1: .43, s0: .33, s1: .26, sy: A - .06, deck: .28, rx: .41, hr: .3, D: .44, but: .14, door: [.13, .14, .045] },
    { ph: .11, pw0: .46, pw1: .43, s0: .34, s1: .28, sy: .38, t0: .25, t1: .23, deck: .29, rx: .42, hr: .34, D: .45, but: .16, door: [.15, .16, .05] },
    { ph: .12, pw0: .46, pw1: .43, s0: .36, s1: .3, sy: .48, t0: .255, t1: .235, deck: .3, rx: .43, hr: .38, D: .46, but: .24, door: [.17, .2, .055] },
  ][tier];
  const E = A + .28; // eave: the front eave clears the bow tips when it aims backwards and recoils
  arrowShade(g, E + L.hr);
  // 1. battered plinth: full-width footing
  g.matWith('stone', 1.35, () => arrowSq(g, 0, L.ph, L.pw0, L.pw1, P.stoneD));
  // 2. battered stone stage + leaning corner buttresses
  const y0 = L.ph, y1 = L.sy, ws = y => L.s0 + (L.s1 - L.s0) * (y - y0) / (y1 - y0);
  g.matWith('stone', 1, () => {
    arrowSq(g, y0, y1, L.s0, L.s1, P.stone, { noTop: 1 });
    for (const [sx, sz] of C4) { const yb = y0 + L.but, wb = ws(yb); arrowFrustum(g, [sx * (L.s0 + .005), y0, sz * (L.s0 + .005)], .085, .085, [sx * (wb - .005), yb, sz * (wb - .005)], .035, .035, P.stoneW, { top: P.cap }); }
  });
  const tilt = -Math.atan((L.s0 - L.s1) / (y1 - y0));
  g.with(T(0, y0, L.s0 + .004, 0, tilt), () => arrowDoor(g, rnd, L.door[0], L.door[1], { ring: L.door[2] }));
  g.box(0, y0 + .008, L.s0 + .05, L.door[0] + .08, .016, .07, P.cap, { noBot: true }); // door step
  if (tier) for (const s of [-1, 1]) g.with(T(0, 0, 0, s * Math.PI / 2), () => { const ym = (y0 + y1) / 2 + .04, z = ws(ym) + .002; g.with(T(0, ym, z, 0, tilt), () => { arrowSlab(g, [[-.035, -.07], [.035, -.07], [.035, .07], [-.035, .07]], -.004, .016, P.cap, .006, 15); g.quad([-.012, -.055, .0125], [.012, -.055, .0125], [.012, .055, .0125], [-.012, .055, .0125], P.dark); }); });
  if (tier) {
    // 3. string course, then the timber stage (L3: wrapped in a shingle skirt roof = second roofed stage)
    g.matWith('stone', .7, () => arrowLedge(g, y1, L.s1, .035, .045, P.cap, { top: P.capD }));
    const t0 = y1 + .045;
    arrowTimber(g, rnd, t0, A - .06, L.t0, L.t1, { brace: tier === 1 });
    if (tier === 2) {
      const ye = t0 + .03, yr = ye + .14, we = L.s1 + .09;
      arrowSq(g, t0 - .005, ye, L.s1 + .03, we, P.beam, { noTop: 1 });
      arrowSq(g, ye, ye + .025, we, we, P.beam, { noTop: 1 });
      g.matWith('shingle', .85, () => arrowSq(g, ye + .025, yr, we, L.t1 - .005, P.roof, { noTop: 1 })); // top edge tucked inside the plank wall
      g.with(T(0, A - .075, L.t1 + .006), () => arrowBanner(g, .13, .12, P.cloth, P.gold, { emblem: 1 }));
    } else g.with(T(0, A - .075, L.t1 + .006), () => arrowBanner(g, .12, .15, P.cloth, P.gold, { emblem: 1 })); // rod rests on the planks
  }
  // 4. lookout deck on brackets + rail on the open front
  const hw = L.deck, zF = .01, zB = zF - L.D, zP = zF - .19, zD = -hw - .06, Xp = hw - .04; // posts stay outside the ballista's sweep
  arrowDeck(g, rnd, A, hw, zD, tier ? L.t1 : L.s1, zP);
  g.matWith('iron', .5, () => g.cyl(0, A, ARROW_ZP, .125, .125, .012, 10, P.iron, { top: P.ironD })); // ballista turntable
  // 5. the hood: roof slab (front eave cantilevered past the posts, clear of the ballista's sweep), posts dying into it, plank back wall
  const H = arrowHipHood(g, rnd, { E, hr: L.hr, rx: L.rx, zB, zF, t: .045, ms: tier ? 1.05 : .95 });
  for (const s of [-1, 1]) {
    for (const z of [zP, zD + .035]) arrowFrustum(g, [s * Xp, A, z], .03, .03, [s * Xp, H.under(s * (Xp + .03), z) + .012, z], .026, .026, P.beam, { top: P.beam });
    g.matWith('iron', .5, () => arrowSq(g, A, A + .05, .036, .036, P.iron, { x: s * Xp, z: zP }));
    arrowBeam(g, [s * Xp, A + .1, zD + .05], [s * Xp, H.under(s * Xp, zP - .03) - .01, zP - .03], .022, .028, P.beam); // side brace
  }
  const bz = zD + .035, bt = H.under(0, bz) - .004;
  g.matWith('wood', .8, () => arrowFace(g, [[-Xp, A, bz], [Xp, A, bz], [Xp, bt, bz], [-Xp, bt, bz]], P.woodD, [0, A + .1, 0]));
  // 6. finials + pennants on the ridge (L3: one at each ridge end)
  const fx = tier === 2 ? [-H.rr, H.rr] : [0];
  for (const x of fx) arrowFinial(g, x, H.Y + .02, H.zr, .13 + tier * .02, { len: .19 + tier * .03 });
  if (tier === 2) for (const s of [-1, 1]) spike(g, [s * (hw - .02), A + .09, hw - .02], [s * (hw + .015), A + .19, hw + .01], .016, P.iron, P.steel, .5);
  // 7. boulders + tufts on the plinth ledge
  const pl = L.pw1 - .045, py = L.ph;
  arrowBoulders(g, rnd, tier === 0 ? [[pl * .55, py, pl, .05], [-pl, py, pl * .2, .045]] : [[pl * .6, py, pl, .055], [-pl, py, pl * .25, .05], [pl, py, -pl * .4, .045]]);
  arrowTuft(g, rnd, -pl * .5, py, pl); arrowTuft(g, rnd, pl, py, pl * .3);
  g.jit = jit; g.bake = null;
};

/* ---------- ballista: mount (yaw), bow (yaw + recoil), string (snaps forward), bolt (reloads) ---------- */
function arrowDyn(tier) {
  const P = ARROW_PAL, k = ARROW_BK[tier], tag = 'arrow_', lw = '#7c5b3c', lw2 = '#5c4330', PV = ARROW_PIV;
  const prep = g => { g.jit = .04; g.bake = (Q, nx, ny, nz, c) => { const f = ny > .6 ? 1.15 : ny < -.5 ? .6 : 1; return [c[0] * f, c[1] * f, c[2] * f]; }; };
  return {
    mount: dynMesh(tag + 'mount' + tier, g => {
      prep(g);
      g.cyl(0, .012, 0, .1 * k, .094 * k, .026, 8, P.woodD, { top: P.wood });
      arrowFrustum(g, [0, .038, 0], .03, .03, [0, PV - .036, 0], .024, .024, P.beam, { top: P.beam });
      for (const s of [-1, 1]) { arrowFrustum(g, [s * .04 * k, PV - .045, 0], .012, .034, [s * .04 * k, PV + .012, 0], .01, .022, P.woodL, { top: P.woodL }); arrowBeam(g, [s * .07 * k, .038, 0], [s * .022, PV - .05, 0], .018, .018, P.beam, { ends: false }); }
      g.box(0, PV - .042, 0, .1 * k, .016, .07, P.iron, { noBot: true });
      g.with(T(0, PV, 0, 0, 0, Math.PI / 2), () => g.cyl(0, -.058 * k, 0, .011, .011, .116 * k, 5, P.ironL));
    }),
    bow: dynMesh(tag + 'bow' + tier, g => {
      prep(g);
      const y = .01, zb = .14 * k, tx = .25 * k, tz = .05 * k;
      arrowBeam(g, [0, y, -.2 * k], [0, y, .165 * k], .05, .042, lw2); // ends flush with the prod: the drawn bolt's head stays clear
      g.box(0, y + .022, 0, .016, .006, .34 * k, P.beam);
      for (const z of [.06 * k, -.12 * k]) g.box(0, y, z, .056, .048, .018, P.iron, { noBot: true });
      // prod block with a slot on top: the bolt rides in the slot (never touches the block) when it is drawn or reloaded
      g.box(0, y - .0045, zb, .11 * k, .049, .05, P.woodD, { top: P.wood });
      for (const s of [-1, 1]) g.box(s * (.0095 + (.055 * k - .0095) / 2), y + .0325, zb, .055 * k - .0095, .023, .05, P.woodD, { top: P.wood, noBot: true });
      for (const s of [-1, 1]) {
        g.cyl(s * .04 * k, y - .036, zb, .02, .02, .08, 5, P.rope, { top: P.rope });
        const a = [s * .05 * k, y + .012, zb + .01], m = [s * .15 * k, y + .018, zb - .01], tp = [s * tx, y + .04, tz];
        arrowBeam(g, a, m, .042, .038, lw); arrowBeam(g, m, tp, .032, .03, lw);
        g.box(tp[0], tp[1], tp[2], .04, .036, .04, P.iron, { top: P.ironL });
        if (tier === 2) spike(g, tp, [tp[0], tp[1] + .004, tp[2] + .055], .012, P.iron, P.steel, .6); // forward: stays inside the sweep radius
      }
      g.with(T(0, y - .004, -.18 * k, 0, 0, Math.PI / 2), () => g.cyl(0, -.06 * k, 0, .022, .022, .12 * k, 5, P.woodL));
      if (tier) g.box(0, y, zb + .03, .09 * k, .04, .01, P.iron);
    }),
    string: dynMesh(tag + 'string' + tier, g => { for (const s of [-1, 1]) g.seg([s * .25 * k, .024, 0], [0, 0, -.17 * k], .007, '#e0d4b0'); }),
    bolt: dynMesh(tag + 'bolt' + tier, g => {
      g.jit = .02;
      arrowBeam(g, [0, .042, -.16 * k], [0, .042, .21 * k], .013, .013, P.bolt);
      g.with(T(0, .042, .21 * k, 0, Math.PI / 2), () => g.cyl(0, 0, 0, .022, 0, .07, 4, P.steel, { rot: Math.PI / 4 }));
      for (const s of [-1, 1]) g.tri([0, .044, -.16 * k], [0, .044, -.09 * k], [s * .03, .046, -.175 * k], P.cloth);
    }),
  };
}
// Attack animation (all driven by t.windup / t.shotT; rigid parts only, the string is the one elastic piece):
//  anticipation: the windlass cranks the string past its rest draw, the bolt rides back with it, the bow leans back and
//                tips its nose up, with a tension shiver at full draw;
//  release (shotT 0): the string snaps straight in one frame (quivers), the bolt is gone, a flash at the prod;
//  recoil: the bow kicks back along the aim (two decaying bumps) and pitches up, overshooting nose-down; the mount jolts;
//  settle + reload: the string is re-cocked (.06-.2 s) and a new bolt drops into the prod's slot (.1-.19 s).
TOWER_DRAW.arrow = function (t, tier, A, an) {
  const D = arrowDyn(tier), k = ARROW_BK[tier], s = t.shotT == null ? 9 : t.shotT, w = clamp(t.windup || 0, 0, 1), we = w * w * (3 - 2 * w);
  const sa = Math.sin(t.ang), ca = Math.cos(t.ang), px = t.x, pz = t.y + ARROW_ZP;
  const kick = s < 1.5 ? Math.exp(-s * 9) * Math.sin(s * 30) : 0, kp = s < 1.5 ? Math.exp(-s * 8) * Math.sin(s * 24 + .35) : 0;
  const shiver = .005 * Math.sin(vt * 83 + an) * clamp((w - .7) / .3, 0, 1);
  const back = .07 * k * Math.max(0, kick) + .016 * we, jolt = .018 * Math.max(0, kick); // one-sided: a forward overshoot would push the bolt into the deck posts
  M4.trs(_m, px - sa * jolt, A, pz - ca * jolt, t.ang); item(D.mount, _m, { shadow: false });
  M4.trs(_m, px - sa * back, A + ARROW_PIV, pz - ca * back, t.ang + shiver, -.09 * we - .2 * kp); item(D.bow, _m); // kick pitch <= .15 rad: the prod stays under the hood's front eave
  // string: rest draw 1 (nock .17k behind the tip line), anticipation draws to 1.2 (bolt head stays ahead of the prod); released = .03 + quiver
  const r = s > 5 ? 1 : clamp((s - .06) / .14, 0, 1), rr = r * r * (3 - 2 * r), draw = rr * (1 + .2 * we);
  const sz = Math.max(.03, draw + (1 - rr) * .2 * Math.exp(-s * 18) * Math.abs(Math.sin(s * 52)));
  M4.mul(_m2, _m, M4.trs(_m3, 0, .03, .055 * k, 0, 0, 0, 1, 1, sz)); item(D.string, _m2, { shadow: false });
  // bolt: rides on the nock; after a shot a fresh one drops into the slot
  if (s > .1) {
    const e = s > 5 ? 1 : clamp((s - .1) / .09, 0, 1), ee = 1 - (1 - e) * (1 - e), dz = -.17 * k * (Math.max(1, draw) - 1); // never ahead of its rest seat
    M4.mul(_m2, _m, M4.trs(_m3, 0, .03 * (1 - ee), dz, 0)); item(D.bolt, _m2, { shadow: false }); // dropped straight down into the slot
  }
  // glint building on the bolt head as the string strains (reads at game size where the draw itself is ~1 px)
  if (we > .02 && s > .19) { const g = M4.xf(_m, 0, .042, .21 * k - .17 * k * (Math.max(1, draw) - 1) + .03); QADD.bill(RD, g[0], g[1], g[2], .035 + .065 * we, .035 + .065 * we, [1, .9, .6, .2 + .55 * we * (.75 + .25 * Math.sin(vt * 31 + an))], 1, 0); }
  // release flash at the prod + a short launch streak along the aim
  if (s < .09) {
    const f = 1 - s / .09, p = M4.xf(_m, 0, .045, .2 * k), q = M4.xf(_m, 0, .07, .2 * k + .5);
    QADD.bill(RD, p[0], p[1], p[2], .2 + .12 * f, .2 + .12 * f, [1, .85, .55, f], 11, 1 + (t.shots || 0) % 4);
    QADD.bill(RD, p[0], p[1], p[2], .12, .12, [1, .97, .85, f], 1, 0);
    if (s < .05) QADD.beam(RD, p, q, .035 * f, [1, .9, .7, .8 * f]);
  }
  // wood dust shaken off the deck by the kick
  if (s < .45) for (let n = 0; n < 3; n++) {
    const a = t.ang + Math.PI + (n - 1) * .9, u = s / .45, d = .12 + .16 * Math.sqrt(u);
    QA.bill(RD, px + Math.sin(a) * d, A + .03 + .08 * u, pz + Math.cos(a) * d, .05 + .07 * u, .05 + .07 * u, [.62, .52, .4, .45 * (1 - u) * (1 - u)], 9, n + (t.shots || 0));
  }
};

/* ================= TOWER: CANNON (bastion) =================
   Owned file: static mesh builder (TOWER_BUILD.cannon), per-frame dynamic parts (TOWER_DRAW.cannon).
   A = anchor height for this tier (ANCH.cannon) = top of the turntable dais; projectile origin = TOWER_TOP.cannon[tier].
   Silhouette: a very squat, wide, battered octagonal drum (L2/L3 add stepped drum stages) bound with thick iron
   bands, an overhanging corbelled cornice + chunky merlons, and a HUGE black-iron cannon on a raised turntable as
   the crown. Powder kegs and a shot pyramid sit in the free corners of the cell. Uses the kit in arrow.js. */

ANCH.cannon = [.56, .86, 1.14];
const CANNON_PAL = { iron: '#2c2a28', ironB: '#2e2c2a', bronze: '#b0823e', bore: '#0b0807', wood: '#4e3320', woodL: '#5e4029', red: '#9a2c1f', redD: '#6e1f16', keg: '#7a4f2a', shot: '#2c2a28' };
// k: carriage scale, r: bore-ring radius, Lb/Lf: barrel length behind/ahead of the trunnions (muzzle <= .52 from the
// centre so it never pokes into a neighbouring tower), hp: trunnion height above the turntable
const CANNON_K = [{ k: 1, r: .09, Lb: .19, Lf: .44, hp: .2 }, { k: 1.1, r: .1, Lb: .21, Lf: .48, hp: .215 }, { k: 1.2, r: .112, Lb: .23, Lf: .52, hp: .235 }];
// offset for dynamic meshes that use procedural materials: built this far up and drawn this far down, so the shader's
// foot contact-shadow (object-space y < .45) never darkens them. The barrel is plain-coloured now, so 0.
const CANNON_OFF = 0;
TOWER_TOP.cannon = ANCH.cannon.map((a, i) => +(a + CANNON_K[i].hp + .02).toFixed(2));
TOWER_EXTRA.cannon = [.3, .32, .34];

// iron band hugging a battered octagonal drum (apothem a0 at y -> a1 at y + h), with big rivets on the front faces
function cannonBand(g, y, h, a0, a1, o = {}) {
  const P = ARROW_PAL, d = o.d || .018;
  g.matWith('iron', .6, () => arrowDrum(g, [[a0 - .004, y - .004], [a0 + d, y + .004], [a1 + d, y + h - .004], [a1 - .004, y + h + .004]], 8, P.iron));
  const a = (a0 + a1) / 2 + d + .002, ym = y + h / 2;
  for (let f = 0; f < 8; f++) { const th = f * Math.PI / 4; if (Math.sin(th) < -.1) continue; g.with(T(Math.cos(th) * a, ym, Math.sin(th) * a, Math.PI / 2 - th), () => { arrowRivet(g, -.06, 0, 0, .014, P.rivet); arrowRivet(g, .06, 0, 0, .014, P.rivet); }); }
}
// chunky merlon / corbel ring on the faces of an octagon: fn(frame) is called in each face frame (face looks down +z)
function cannonFaces(g, fn, back) { for (let f = 0; f < 8; f++) { const th = f * Math.PI / 4; if (!back && Math.sin(th) < -.75) continue; g.with(T(0, 0, 0, Math.PI / 2 - th), () => fn(f, th)); } }
// riveted iron armour plate on a battered face (face frame; plate from y0 to y1 at apothem a0 -> a1)
function cannonPlate(g, y0, y1, a0, a1, w, o = {}) {
  const P = ARROW_PAL, tilt = -Math.atan((a0 - a1) / (y1 - y0)), h = Math.hypot(y1 - y0, a0 - a1);
  g.with(T(0, y0, a0 + .002, 0, tilt), () => {
    g.matWith('iron', .5, () => arrowSlab(g, [[-w / 2, 0], [w / 2, 0], [w / 2 * .92, h], [-w / 2 * .92, h]], 0, .02, o.col || P.ironD, .008, 15));
    for (const [x, y] of [[-.36, .14], [.36, .14], [-.34, .86], [.34, .86]]) arrowRivet(g, x * w, y * h, .022, .015, P.rivet);
    if (o.spike) spike(g, [0, h * .55, .015], [0, h * .6, .09], .022, P.iron, P.steel, .55);
  });
}
// story props in the free corners of the cell: hooped powder kegs, a pyramid of shot
function cannonKeg(g, x, y, z, s = 1, rot = 0) {
  const C = CANNON_PAL, P = ARROW_PAL, r = .05 * s, h = .12 * s;
  g.matWith('wood', .4, () => g.lathe(x, y, z, [[r * .86, 0], [r, h * .3], [r, h * .7], [r * .86, h], [0, h]], 8, C.keg, { rot }));
  for (const t of [.12, .82]) g.cyl(x, y + h * t, z, r * (t < .5 ? .93 : .95) + .004, r * (t < .5 ? .97 : .9) + .004, h * .08, 8, P.iron, { rot });
}
function cannonShot(g, x, y, z, br) {
  for (const [dx, dz, dy] of [[-1, -.6, 0], [1, -.6, 0], [0, 1.1, 0], [0, -.05, 1.45]]) g.sphere(x + dx * br * 1.02, y + br + dy * br, z + dz * br, br, br, br, 6, 4, CANNON_PAL.shot);
}

TOWER_BUILD.cannon = function (g, tier, A, rnd) {
  const P = ARROW_PAL, C = CANNON_PAL, jit = g.jit; g.jit = .03;
  arrowShade(g, A + .1, .82, .95);
  // drum stages bottom-up: [y0, y1, a0, a1]; between stages an overhanging iron-capped string course
  const S = [
    [[.085, A - .2, .43, .35]],
    [[.085, .4, .43, .38], [.455, A - .2, .335, .31]],
    [[.085, .46, .435, .385], [.515, A - .2, .34, .295]],
  ][tier];
  // flared plinth
  g.matWith('stone', 1.35, () => arrowDrum(g, [[.46, 0], [.445, .07], [S[0][2] + .005, .085]], 8, P.stoneD));
  S.forEach(([y0, y1, a0, a1], i) => {
    g.matWith('stone', 1.05 - i * .1, () => arrowDrum(g, [[a0, y0 - .002], [a1, y1]], 8, i ? P.stoneC : P.stone));
    if (i < S.length - 1) { // string course to the next stage
      const n = S[i + 1];
      g.matWith('stone', .7, () => arrowDrum(g, [[a1 - .004, y1 - .025], [a1 + .028, y1 + .005], [a1 + .028, n[0] - .012], [n[2] + .005, n[0] - .002]], 8, P.cap));
      cannonBand(g, n[0] - .012 - .03, .03, a1 + .028, a1 + .028, { d: .012 });
    }
  });
  // iron bands on the lower drum (thick, riveted)
  const s0 = S[0], aAt = (s, y) => s[2] + (s[3] - s[2]) * (y - s[0]) / (s[1] - s[0]);
  // (bands sit clear of the door: above it on L1, on the upper drums for L2/L3)
  const bandAt = (s, y, h) => cannonBand(g, y, h, aAt(s, y), aAt(s, y + h));
  if (tier === 0) bandAt(s0, .3, .045); else bandAt(S[1], S[1][1] - .085, .045);
  // cornice + parapet ring + flagstone floor
  const top = S[S.length - 1], aT = top[3], ao = aT + .06, ai = aT - .01, yc = top[1], yp = A - .03, yf = A - .08, rd = .232 + tier * .01;
  g.matWith('stone', .75, () => arrowDrum(g, [[aT - .004, yc - .004], [ao, yc + .04], [ao, yp], [ai, yp], [ai, yf]], 8, P.cap));
  g.matWith('cobble', .8, () => arrowDrum(g, [[ai + .002, yf], [0, yf]], 8, P.cobble));
  // corbels under the cornice, merlons over them
  const mh = A + (tier === 2 ? .035 : .05) - yp; // L3's narrow parapet: merlons kept under the recoiling breech
  cannonFaces(g, (f) => {
    g.matWith('stone', .6, () => arrowFrustum(g, [0, yc - .1, aT + .004], .032, .01, [0, yc + .03, (aT + ao) / 2], .038, (ao - aT) / 2 + .002, P.capD, { skip: 1, top: P.capD }));
    g.matWith('stone', .7, () => arrowFrustum(g, [0, yp, (ao + ai) / 2], .085 + tier * .006, (ao - ai) / 2, [0, yp + mh, (ao + ai) / 2 - .004], .075 + tier * .006, (ao - ai) / 2 - .008, P.stone, { top: P.cap }));
    if (tier === 2 && f % 2 === 0) { g.matWith('iron', .5, () => arrowSq(g, yp + mh, yp + mh + .016, .085, .085, P.iron, { z: (ao + ai) / 2 - .004, d0: (ao - ai) / 2, d1: (ao - ai) / 2 })); spike(g, [0, yp + mh + .01, (ao + ai) / 2 + .02], [0, yp + mh + .045, ao + .06], .02, P.iron, P.steel, .55); } // outward + low: under the barrel's sweep
  }, tier === 2);
  // raised turntable dais the cannon sits on (keeps the recoiling breech clear of the merlons)
  g.matWith('stone', .6, () => g.cyl(0, yf - .002, 0, rd, rd - .01, A - .014 - yf + .002, 10, P.capD, { top: P.cap })); // top hidden under the iron ring (no coplanar caps)
  g.matWith('iron', .5, () => g.cyl(0, A - .014, 0, rd + .003, rd + .003, .014, 10, P.iron, { top: P.ironD }));
  // door on the front face of the lower drum; gunports / armour higher up
  const tilt0 = -Math.atan((s0[2] - s0[3]) / (s0[1] - s0[0]));
  g.with(T(0, s0[0], s0[2] - .012, 0, tilt0), () => arrowDoor(g, rnd, tier ? .14 : .13, tier ? .16 : .14, { ring: .045, dep: .024 })); // shallow arch: the drum sits near the cell edge
  if (tier) {
    const up = S[1];
    cannonFaces(g, (f) => {
      if (f === 2 || (tier === 2 && f !== 0 && f !== 4)) cannonPlate(g, up[0] + .03, up[1] - .03, aAt(up, up[0] + .03), aAt(up, up[1] - .03), .17, { spike: tier === 2 && f === 2 });
      else if (f === 1 || f === 3) { // gunport
        const y = (up[0] + up[1]) / 2, a = aAt(up, y), tl = -Math.atan((up[2] - up[3]) / (up[1] - up[0]));
        g.with(T(0, y, a + .002, 0, tl), () => { arrowSlab(g, [[-.05, -.045], [.05, -.045], [.05, .045], [-.05, .045]], -.004, .02, P.cap, .007, 15); g.quad([-.03, -.028, .0165], [.03, -.028, .0165], [.03, .028, .0165], [-.03, .028, .0165], P.dark); });
      }
    });
  }
  // props: kegs + shot in the free front corners of the cell (outside the octagonal plinth, inside the footprint),
  // and ready powder + shot on the wall-walk beside the gun (below the sweep of the barrel)
  cannonKeg(g, .362, 0, .37, 1, .3);
  if (tier) cannonKeg(g, .362, .12, .37, .78, .9);
  cannonShot(g, -.372, 0, .378, .034);
  const rw = (ai + rd) / 2;
  if (tier < 2) { cannonKeg(g, Math.cos(2.55) * rw, yf, Math.sin(2.55) * rw, tier ? .7 : .85, .4); cannonShot(g, Math.cos(.75) * rw, yf, Math.sin(.75) * rw, .026); }
  arrowTuft(g, rnd, .3, 0, .43); arrowTuft(g, rnd, -.43, 0, .3); arrowTuft(g, rnd, .43, 0, .28);
  g.jit = jit; g.bake = null;
};

