  anvil: '#5a5650', anvilT: '#4c4844', head: '#a0927a', headD: '#857860',
  wood: '#5a3a1e', woodD: '#4a2f18', woodL: '#6a4626', ledge: '#4e3219', ledgeT: '#5c3d20', beam: '#3f2814', leather: '#5e3c22', paint: '#9c3a22',
  bone: '#e2d6b8', boneD: '#c4b390', iron: '#4a4642', ironD: '#3a3734', ironL: '#6a655e', rune: '#ffb347', eye: '#ffd36a',
