  const hr = M4.xf(_m2, 0, L.Hh / 2, L.D / 2 + .03), ht = M4.xf(_m2, 0, L.Hh + .03, 0), gl = .18 + .7 * e + 1.2 * fl;
  QADD.bill(RD, hr[0], hr[1], hr[2], .13 + .12 * e, .13 + .12 * e, [1, .62, .22, .35 * gl], 1, 0);
  QADD.bill(RD, ht[0], ht[1], ht[2], .1 + .1 * e, .1 + .1 * e, [1, .62, .22, .25 * gl], 1, 0);
  const FC = earthPole(L), eyY = FC.fy + .018, eyZ = pz + FC.zf(FC.fy) + .012;
  for (const s of [-1, 1]) QADD.bill(RD, px + s * .05, eyY, eyZ, .05 + .06 * e, .05 + .06 * e, [1, .75, .3, .25 + .6 * e + .8 * fl], 1, 0);
