  D.st.forEach(([y0, y1, r0, r1], i) => storm_lathe(g, [[r0, y0], [r1, y1]], [12, 10, 10][i], i === 0 ? STORM.stone : STORM.stoneW, 'stone', [1.25, 1, .85][i]));
