  QADD.bill(RD, ox + cdx * kc, oy + cdy * kc, oz + cdz * kc, .075 * S * (1 + .6 * e), .075 * S * (1 + .6 * e), [.8, .78, 1, .75 + .25 * e], 1, 0);
