  // Eclipse Orb: the dark disc gathers over the tower in the moments before the sun goes out
  if (has('eclipse') && t.tg && t.eclT != null && t.eclT < 1.6) { const u = 1 - t.eclT / 1.6, col = rc4('eclipse'), y = crownY(t) + .15; QA.bill(RD, t.x, y, t.y, .14 + .24 * u, .14 + .24 * u, [.04, .02, .07, .85 * u], 5, 0); QADD.bill(RD, t.x, y, t.y, .2 + .3 * u, .2 + .3 * u, [col[0], col[1], col[2], .6 * u], 3, .12); }
