        if (!ENV.die) ENV.die = dynMesh('rdie', g => { g.box(0, 0, 0, .1, .1, .1, '#efe6cc'); for (const [x, y, z] of [[0, .051, 0], [.051, .02, .02], [.051, -.02, -.02], [-.051, 0, 0], [0, 0, .051], [.02, -.051, .02], [-.02, -.051, -.02]]) g.box(x, y, z, Math.abs(x) > .05 ? .004 : .018, Math.abs(y) > .05 ? .004 : .018, Math.abs(z) > .05 ? .004 : .018, '#2a1a12'); });
        const up = f.six ? 1.7 : .7, tt = f.max - f.life, h = f.h + up * tt - (f.six ? 3.5 : 6) * tt * tt * .5 + (f.six ? .2 : 0);
