  const poly = pts => () => { X.moveTo(pts[0][0], pts[0][1]); for (let i = 1; i < pts.length; i++) X.lineTo(pts[i][0], pts[i][1]); X.closePath(); };
  const star = (cx, cy, r1, r2, n, rot = -Math.PI / 2) => () => { for (let i = 0; i < n * 2; i++) { const a = rot + i * Math.PI / n, r = i % 2 ? r2 : r1; i ? X.lineTo(cx + Math.cos(a) * r, cy + Math.sin(a) * r) : X.moveTo(cx + Math.cos(a) * r, cy + Math.sin(a) * r); } X.closePath(); };
  const glow = (cx, cy, r, col, a = .7) => { const g = X.createRadialGradient(cx, cy, 0, cx, cy, r); const c = hex(col); g.addColorStop(0, `rgba(${c},${a})`); g.addColorStop(1, `rgba(${c},0)`); X.fillStyle = g; X.fillRect(cx - r, cy - r, r * 2, r * 2); };
