    shell: () => { X.save(); X.translate(50, 52); X.rotate(-.75); fill(() => { X.moveTo(-30, -14); X.lineTo(14, -14); X.quadraticCurveTo(40, -14, 42, 0); X.quadraticCurveTo(40, 14, 14, 14); X.lineTo(-30, 14); X.closePath(); }, '#6a6a76'); line([[-22, -14], [-22, 14]], 4, C.gold); X.restore(); glow(22, 80, 18, '#ffb24a', .7); },
    tomb: () => { fill(poly([[50, 10], [88, 30], [88, 74], [50, 92], [12, 74], [12, 30]]), '#bfe8ff'); skull(50, 52, 26, '#5a7a9a'); X.globalAlpha = .35; fill(poly([[50, 10], [88, 30], [50, 50], [12, 30]]), C.white, { ow: 0.1 }); X.globalAlpha = 1; },
    rime: () => { fill(poly([[6, 70], [94, 70], [94, 90], [6, 90]]), '#5a6a7a'); for (const [x, h] of [[16, 30], [32, 48], [50, 38], [68, 54], [84, 32]]) fill(poly([[x - 7, 72], [x, 72 - h], [x + 7, 72]]), C.ice, { ow: 4 }); flake(78, 20, 9, C.white, 2.5); },
    heat: () => { for (const x of [28, 50, 72]) { const pts = []; for (let i = 0; i <= 20; i++) pts.push([x + Math.sin(i * .6) * 6, 90 - i * 3.6]); line(pts, 5, C.fire); } glow(50, 90, 26, '#ff8a2a', .6); },
    fist: () => { fill(() => { X.roundRect ? X.roundRect(22, 26, 56, 48, 14) : X.rect(22, 26, 56, 48); }, '#c89a6a'); for (const x of [36, 50, 64]) line([[x, 28], [x, 46]], 2.5, '#6a4a2a'); fill(poly([[22, 50], [10, 38], [16, 30], [30, 42]]), '#c89a6a', { ow: 5 }); fill(poly([[30, 74], [70, 74], [66, 92], [34, 92]]), C.rock); },
    tremor: () => { for (const y of [30, 50, 70]) { const pts = []; for (let i = 0; i <= 24; i++) pts.push([8 + i * 3.5, y + Math.sin(i * 1.1 + y) * 6]); line(pts, 5, C.rock); } },
