    beaker: () => { fill(poly([[40, 12], [60, 12], [60, 38], [84, 88], [16, 88], [40, 38]]), '#d8e8d0'); fill(poly([[30, 64], [70, 64], [84, 88], [16, 88]]), C.pois, { ow: 2 }); for (const [x, y, r] of [[44, 52, 5], [56, 40, 4], [50, 28, 3]]) fill(circ(x, y, r), '#c6ff7a', { ow: 2 }); },
    disint: () => { glow(50, 50, 48, '#c08cff', .7); for (let i = 0; i < 6; i++) { const a = i / 6 * 6.28 + .3; X.save(); X.translate(50 + Math.cos(a) * (14 + i % 2 * 10), 50 + Math.sin(a) * (14 + i % 2 * 10)); X.rotate(a); fill(poly([[-9, -7], [10, -4], [6, 9], [-8, 6]]), C.arc, { ow: 4 }); X.restore(); } fill(circ(50, 50, 9), C.white, { ow: 3 }); },
    auraring: () => { glow(50, 50, 48, '#ffe08a', .7); for (const r of [38, 26, 14]) arcL(50, 50, r, 0, 6.29, 4, C.holy); fill(circ(50, 50, 6), C.white, { ow: 3 }); },
    cross: () => { glow(50, 46, 44, '#ffe08a', .6); fill(poly([[42, 10], [58, 10], [58, 30], [80, 30], [80, 46], [58, 46], [58, 90], [42, 90], [42, 46], [20, 46], [20, 30], [42, 30]]), C.holy); for (const [x, y] of [[18, 74], [82, 70]]) fill(() => { X.arc(x, y, 9, Math.PI, 0); X.lineTo(x + 9, y + 12); X.lineTo(x, y + 8); X.lineTo(x - 9, y + 12); X.closePath(); }, '#b8c8d8', { ow: 4 }); },
    pact: () => { glow(50, 50, 48, '#a46cff', .6); arcL(50, 50, 38, 0, 6.29, 4, C.shad); const pts = []; for (let i = 0; i <= 5; i++) { const a = -Math.PI / 2 + i * 4 * Math.PI / 5; pts.push([50 + Math.cos(a) * 34, 50 + Math.sin(a) * 34]); } line(pts, 3.5, '#d8b8ff'); fill(circ(50, 50, 7), C.blood, { ow: 3 }); },
