    skull: () => { skull(50, 46, 40); line([[50, 4], [50, 22]], 4, C.blood); line([[50, 74], [50, 96]], 4, C.blood); },
    eye: () => { glow(50, 50, 46, '#ffd36a', .35); eye(50, 50, 38, C.gold, '#2a1406'); },
