  let guest = null, nextGuest = 3 + R() * 4;   // (a phone's narrow slice of the painting seldom has room for a bird: an insect comes instead)
  const gap = () => W < 700 ? 12 + R() * 16 : 5 + R() * 11;   // (each kind every 10-30 s or so; a phone sees fewer)

  // the fog they hang in: faint patches at the edges, drifting a little, laid over them
  const veil = []; for (let i = 0; i < 12; i++) { const E = TFX_EDGES[Math.floor(R() * TFX_EDGES.length)]; veil.push({ u: E[0] + (R() - .5) * .05, v: E[1] + (R() - .5) * .04, w: .05 + R() * .06, p: R() * TAU, a: .035 + R() * .035 }); }
  // the wisps: an emitter wanders round each painted wisp and leaves a rising, curling trail
  const smoke = [];
  const emit = (w, t) => { const [su, sv, st] = w, k = su * 40;
    const eu = su + Math.cos(t * .37 + k) * .03 + Math.sin(t * .19 + k * 2) * .015 + (R() - .5) * .02, ev = sv + Math.sin(t * .51 + k) * .035 + (R() - .5) * .02;
    smoke.push({ u: eu, v: ev, vu: (R() - .5) * .008, vv: -.01 - R() * .014, age: 0, life: 3.5 + R() * 3, size: .014 + R() * .02, st, ph: R() * TAU, k, spark: R() < .04, tw: 2 + R() * 5 }); };
