  let h = `<div class="wt-h"><i class="wt-n" style="color:${unitNameCol(t) || hue}">${stEsc(d.name || 'Unit')}</i><i class="wt-k">Tier ${ROMAN[t.tier | 0] || 'I'}</i></div>`
