    if (h.id === 'hivemother' && t.affCh) lbl += ` ×${t.affCh}`;
    if (h.id === 'ih_brewer') lbl += ` ${t.affN || 0}/20`;
    if (h.id === 'sb_beast' && t.affCdT > G.time) lbl += ' (resting)';
