/* Run after heroes and the existing art maps, before UI initialization. Keep existing paintings intact. */
function missingArtApply() {
  const art = MISSING_ART;
  const added = COMPLETION_ART;
  // Supplement only audited gaps. The two redesigned fire spells intentionally retire their old paintings.
  for (const [id, uri] of Object.entries(added.abilities)) {
    const retired = (id === 'cc_pyresigil' || id === 'cc_flamewave') && UI_ART[id] === art.abilities[id];
    if (!UI_ART[id] || retired) UI_ART[id] = uri;
  }
  for (const [id, uri] of Object.entries(added.talents)) if (!TALENT_PAINT.talents[id]) TALENT_PAINT.talents[id] = uri;
  for (const [id, uri] of Object.entries(added.units)) if (!UNIT_ART.units[id]) UNIT_ART.units[id] = uri;
  for (const [id, uri] of Object.entries(added.enemies)) if (!UNIT_ART.enemies[id]) UNIT_ART.enemies[id] = uri;
  for (const [id, uri] of Object.entries(added.heroes)) if (!HERO_ART[id]) HERO_ART[id] = uri;
  for (const [id, uri] of Object.entries(added.commanders)) if (!COMMANDER_ART[id]) COMMANDER_ART[id] = uri;
  for (const [id, uri] of Object.entries(art.abilities)) if (!UI_ART[id]) UI_ART[id] = uri;
  for (const [id, uri] of Object.entries(art.heroes)) if (!HERO_ART[id]) HERO_ART[id] = uri;
  for (const hero of HEROES) {
    const id = hero.spell && hero.spell.id;
    if (id && UI_ART[id] && !SPELL_ART[id]) SPELL_ART[id] = id;
  }
  for (const [id, uri] of Object.entries({ ...art.items, ...TALENT_PAINT.items, ...added.items, ...(added.weapons || {}) })) {
    const key = SHOP[id] ? 'shop-' + id : id;
    if (RELICART[key]) continue;
    RELICART[key] = uri;
    const im = new Image();
    im.onload = () => { RELIC_IMG[key] = im; if (typeof onDirty === 'function') onDirty(); };
    im.src = uri;
  }
  for (const [id, uri] of Object.entries(art.textures)) {
    if (UNIT_TEX[id]) continue;
    const im = new Image();
    im.onload = () => { MAT_SRC = null; };
    UNIT_TEX[id] = { img: im };
    im.src = uri;
  }
}
missingArtApply();

Object.assign(HERO_ART, COMMANDER_FACES);

