const hudCache = {};

function lsGet(k) { try { return localStorage.getItem(k); } catch (e) { return null; } }
function lsSet(k, v) { try { localStorage.setItem(k, v); } catch (e) {} }
function lsDel(k) { try { localStorage.removeItem(k); } catch (e) {} }
/* Saved games: up to three runs in progress, newest first (the title screen's left panel). Each run has its own id;
   it is saved between waves and dropped when it ends. The old single save becomes the first slot. */
const SAVES_KEY = 'runehold.saves.v2', SAVES_MAX = 3;
