  const x = bannerEl.querySelector('.ban-x'); if (x) x.innerHTML = extra || '';
  bannerEl.classList.remove('show', 'long'); void bannerEl.offsetWidth; bannerEl.classList.add('show'); if (extra) bannerEl.classList.add('long');
