  const max = abMax(t), cur = clamp(t.ab.mana, 0, max), w = Math.round(1000 * cur / Math.max(1, max)) / 10 + '%';
  const f = row.querySelector('.mn-fill'), n = row.querySelector('.mn-now'), r = row.querySelector('.mn-rate');
