  { const sk = play && !TW && G.state === 'play' ? streakN() : 0; setText('hStk', sk ? '+' + sk * 10 + '%' : ''); if (hudCache.stkOn !== !!sk) { hudCache.stkOn = !!sk; document.getElementById('hStk').hidden = !sk; } }
