/* ---------- canvas input ---------- */
function setGhost(p) {
  const i = Math.floor(p.x), j = Math.floor(p.y);
  if (!inGrid(i, j)) { G.ghost = null; return; }
  if (G.ghost && G.ghost.i === i && G.ghost.j === j) return;
  const chk = canBuild(i, j), cost = TOWERS[G.buildType].tiers[0].cost;
  G.ghost = { i, j, in: true, ok: chk.ok && G.gold >= cost, msg: chk.msg, path: chk.ok ? tracePath(chk.dist, nextField(chk.dist, chk.blk)) : null };
}
// a double tap on a tower picks up every built tower of its school and tier, to upgrade them together
let lastTowerTap = { t: null, at: 0 };
