function selectGroup(t) {
  const g = towerGroup(t); if (g.length < 2) { select('tower', t); return; }
  G.sel = { kind: 'tower', ref: t, group: g }; G.buildType = null; G.ghost = null; if (TW) TW.menu = false; selVoice(t.def.unit || t.def.id); markDirty();
  toast(`${g.length} ${TOWERS[t.type].name}s at tier ${ROMAN[t.tier]} selected. Upgrade them all at once.`);
}
function tapSelect(p, e) {
  const i = Math.floor(p.x), j = Math.floor(p.y);
  if (G.cast) { if (p.x > -.5 && p.y > -1 && p.x < COLS + .5 && p.y < ROWS + 1) heroCastAt(p.x, p.y); else { G.cast = null; toast('Spell cancelled.'); } markDirty(); return; }   // a hero's aimed spell
  if (G.moveT) {   // a Waystone is moving a tower: this tap picks where
    const t = G.moveT;
    if (!G.towers.includes(t) || G.tAt[idx(i, j)] === t) { G.moveT = null; toast('Move cancelled.'); markDirty(); return; }
    if (moveTowerTo(t, i, j)) toast(`${t.def.name} moved.`);
    markDirty(); return;
  }
  const best = pickCreep(e.clientX, e.clientY);
  if (best) { select('creep', best); if (best.def.eco) toast(best.def.name + ': ' + best.def.eco); return; }   // the pane is small on phones, so say what it does
  const t = inGrid(i, j) && G.tAt[idx(i, j)];
  if (t) {
    const now = performance.now(), dbl = lastTowerTap.t === t && now - lastTowerTap.at < 420; lastTowerTap = { t: dbl ? null : t, at: now };
    if (dbl && !t.def.wall) { selectGroup(t); return; }
    if (G.sel && G.sel.ref === t) deselect(); else select('tower', t); return;
  }
  // the keep: anything below the field, along the wall and the gate
  if (p.y > ROWS + .3 && p.y < ROWS + 5 && p.x > -3 && p.x < COLS + 3) { if (G.sel && G.sel.kind === 'keep') deselect(); else select('keep', null); return; }
  if (G.sel) deselect();
}
