  const used = fix.map(f => f[1]).join(' ').toLowerCase(), kw = ['flyers', 'siege', 'weak to', 'barricade', 'talent', 'interest', 'shatter', 'stun'];
  const know = (G.force && !G.vs ? KNOW_F : KNOW).filter(k => !kw.some(w => used.includes(w) && k.toLowerCase().includes(w)));
