    const by = {}; for (const e of LABF.list) { const k = e.name + (e.top ? '|' : '') + (e.tg ? '#' + e.tg.id : ''); (by[k] = by[k] || []).push(e); }   // (top: drawn over the foes, no depth test; tg: the Element Lab's recolour)
