      hfPatch(x, z, rad * .8, 1.6, { flare: 0, at: 1.1, alive: () => { let l = 0; for (const h of G.hazards || []) if ((h.k === 'fire' || h.k === 'ih_pitch') && h.t > 0 && Math.abs(h.x - x) < .3 && Math.abs(h.z - z) < .3) l = Math.max(l, h.t); return l; } });
