      const V = sdV('censercoal', 'coal'), k = sdOnL('censercoal', 'coal'); if (k == null) continue;
      const u = Math.min(1, z.age / z.T), h = z.h0 + (.2 - z.h0) * u, st = sdSt(z), sz = V.w * (z.o.small ? .7 : z.o.big ? 1.4 : 1) * k;
