      if (now - st.shed > V.every) { st.shed = now; sdShot('spore', z.x, h, z.z, V.trail, .6, { vy: .25, grow: 1.1, p0: .9, p1: 0, a: .85, col: CNF_SMOKE }, 'censercoal', 'coal'); if (lv && Math.random() < .5) cnfEmbers(z.x, h, z.z, 1, .3, .2, 'censercoal', 'coal'); }
