  if (L > .03) { const tl = Math.min(tail, L), k = tl / L, T = [P[0] - dx * k, P[1] - dy * k, P[2] - dz * k]; sdSeg(SDT_SH.BEAM, T, P, w * .5, w * 2.2, { seed, k: 1, a: a * .9, p0: 1, p1: 1.2, p2: tl, col, sp: 2 }, s, l); }
