  sdBill(SDT_SH.GLOW, P, w * 1.5 * br, w * 1.5 * br, { seed: seed + 1, a: a * .9, col }, s, l);
  sdBill(SDT_SH.GLOW, P, w * .75, w * .75, { seed: seed + 2, a: a * .95, col: MGF_HOT }, s, l);
