if (typeof sfxBasicCC === 'function') { const _b = sfxBasicCC; sfxBasicCC = function (p) { if (p && p.k === 'missile' && mgfOn()) return true;   /* (drawn with the frame's cards below: cards queued from here are not gathered) */ return _b.apply(this, arguments); }; }
