    cc_barrage: { unit: 'cc_mageling', force: 'conclave', el: 'seed', name: 'Arcane Barrage', layers: ['missile', 'sparks', 'gather'] },
    cc_sparks: { unit: 'cc_mageling', force: 'conclave', el: 'seed', name: 'Missile Curtain', layers: ['hang', 'missile', 'sparks'] },
