  if (typeof EFX_LNAME_SEED !== 'undefined') Object.assign(EFX_LNAME_SEED, { missile: 'The missile', sparks: 'Its wake of motes, and its landing', gather: 'Light at her hand', hang: 'The hung missiles', orb: 'The orb' });
