    const x = c.x + (c.ox || 0) + (c.kbx || 0), z = c.y + (c.oy || 0) + (c.kbz || 0), by = typeof creepBaseY === 'function' ? creepBaseY(c) : 0, hh = typeof creepH === 'function' ? creepH(c) : .6, fz = c.stunT > 0 && c.stunEl === 'frost', id = c.id || 1;
