  const M = p._sg || (p._sg = { A: [p.x0, p.h0, p.z0], seed: Math.random() * 97, dust: 0 });
  let d = [p.x - M.A[0], (p.h || .5) - M.A[1], p.z - M.A[2]]; const L = Math.hypot(d[0], d[1], d[2]);
  if (L < .02) d = [p.tx - p.x0, 0, p.tz - p.z0];
