    $('#elDist').oninput = e => { L.dist = +e.target.value; e.target.previousElementSibling.querySelector('b').textContent = L.dist.toFixed(1) + ' cells'; };
    $('#elDist').onchange = () => { set('dist', L.dist); stage(); };
