      if ((c.hxShT || 0) < G.time) { c.hxShT = G.time + .3; fxSpark(c.x, c.y, hitH(c), '#c8e6ff', 3); }
      if (c.hxSh <= 0) { c.hxSh = 0; fxShards(c.x, c.y, hitH(c), 14); onToast(`${c.def.name}'s barrier breaks.`); }
