  const cnt = o => Object.keys(o).map(k => `${k}${o[k] > 1 ? '×' + o[k] : ''}`).join(', ');
  const acts = [w.built && 'built ' + cnt(w.built), w.upgraded && 'up ' + cnt(w.upgraded), w.converted && 'wall→ ' + cnt(w.converted), w.sold && 'sold ' + cnt(w.sold)].filter(Boolean);
