  L.push(`${r.mapName || r.map} · ${r.riteName || 'no rite'} · ${r.diffName}${r.chal ? ' · challenge ' + r.chal : ''} · ${r.lives0} lives · started ${r.started.replace('T', ' ').slice(0, 16)}${r.fromWave > 1 ? ` (log from wave ${r.fromWave})` : ''} · build ${r.build}`);
  L.push(r.end ? `**Result: ${r.end.result} at wave ${r.end.wave}**${r.end.cause ? ` · ${r.end.cause}` : ''}` : s.live ? `In play: wave ${s.live.wave} (${s.live.phase}), ${s.live.lives} lives, ${s.live.gold} gold${s.live.tp ? `, ${s.live.tp} talent points unspent` : ''}` : 'Open (not in play)');
  L.push(`Totals: ${T.waves} waves, ${T.kills} slain, ${T.livesLost} lives lost${Object.keys(T.leaksBy).length ? ' (' + Object.keys(T.leaksBy).sort((a, b) => T.leaksBy[b] - T.leaksBy[a]).map(k => `${k} ${T.leaksBy[k]}`).join(', ') + ')' : ''}, gold +${T.earned}/-${T.spent}; top units ${T.topUnits.map(u => `${u[0]} ${plK(u[1])}`).join(', ') || '-'}`);
