  W('qxSkip', f => function () { const had = G.qx && G.qx.offer, r = f.apply(this, arguments); if (had && PL.W && plOn()) PL.W.qx.push('skipped the offer'); return r; });
  W('qxWin', f => function () { const c = G.qx && G.qx.cur, live = c && c.state === 'on', r = f.apply(this, arguments); if (live && PL.W && plOn()) PL.W.qx.push(`won ${(QX[c.id] && QX[c.id].n) || c.id}`); return r; });
  W('qxFail', f => function (why) { const c = G.qx && G.qx.cur, live = c && c.state === 'on', r = f.apply(this, arguments); if (live && PL.W && plOn()) PL.W.qx.push(`failed ${(QX[c.id] && QX[c.id].n) || c.id}: ${why || ''}`.trim()); return r; });
