/* ---- the step machine ---- */
const tutStep = () => TUT.cur && TUT.cur.steps[TUT.cur.k];
function tutEnter() { const c = TUT.cur, s = tutStep(); if (!s) return; c.flags.stepT = Date.now(); if (s.on) s.on(c); if (s.done) tutMarkDone(c.ch.id); }
