  const weak = (d.roles || []).map(r => { const w = (d.boss || d.lead) && ROLE_WEAK_BIG[r] || ROLE_WEAK[r]; return w ? `<b>${tutEsc(ROLE_NAME[r])}:</b> ${tutEsc(w)}` : ''; }).filter(Boolean).join(' · ');
  return `<div class="tc-foe"><p class="tc-fn"><b>${tutEsc(d.name)}</b>${roles.length ? ' · ' + tutEsc(roles.join(' · ')) : ''}${tr ? ' · ' + tutEsc(tr) : ''}</p>${tags}${weak ? `<p class="tc-fw">${weak}</p>` : ''}</div>`;
