// a playtest run: the commander's force on the standard march (outside the Chronicles), set to wave W
function ptStart(hero, W, kind) {
  if (typeof twStop === 'function') twStop();
  const L0 = typeof CAMP_LOCS !== 'undefined' ? CAMP_LOCS[0] : null;
  mapPick = L0 ? L0.map : riteMap(0); setMap(mapPick);
  if (typeof CAMP_NEXT !== 'undefined') CAMP_NEXT = null;
  newGame('normal', null, hero, L0 ? L0.rite : 0);
  G.runId = 'pt' + newRunId(); G.playT = 0;
  const r = ptApply(W, kind);
  if (typeof plBase === 'function') { try { plBase(); } catch (e) {} }
  const n = r.items.length;
  afterStart(`Playtest · wave ${G.wave}`, `Level ${G.lvl}, ${G.tp} talent points to spend, ${G.gold} gold${G.age ? `, a ${AGES[G.age].name}` : ''}${n ? `, ${n} item${n > 1 ? 's' : ''} in the bag` : ''}. Plant a maze, then sound the horn`);
  saveNow();
  return r;
}

/* ---------- the playtest's own save slot ---------- */
function ptSaveGet() {
  let x = null; try { x = JSON.parse(ptLs(PT_SAVE_KEY) || 'null'); } catch (e) {}
  return x && x.s && x.s.playtest && typeof validSave === 'function' && validSave(x.s) ? x : null;
}
function ptSavePut() {
  if (!ptOn() || G.state !== 'play' || G.phase !== 'build') return;
  const s = serialize(); if (!s) return;
  if (!G.runId) G.runId = 'pt' + newRunId();
  ptLs(PT_SAVE_KEY, JSON.stringify({ id: G.runId, at: Date.now(), s }));
}
function ptContinue(x) {
  if (typeof twStop === 'function') twStop();
  restore(x.s); G.runId = x.id;
  afterStart(`Playtest · wave ${G.wave}`, 'Your maze stands as you left it.');
}

/* ---------- the setup screen ---------- */
function ptSetup(back) {
  back = back || titleScreen;
  const hero = typeof heroForRun === 'function' ? heroForRun() : null, f = hero && forceOfHero(hero);
  if (!f) { openHeroPicker(() => ptSetup(back), back, false); return; }
  const H = HERO_BY[hero], pref = ptPrefGet(), sv = ptSaveGet();
  let W = pref.wave, gear = pref.gear;
  const svH = sv && HERO_BY[sv.s.hero];
  showOverlay(`<h2 class="ttl">Playtest start</h2>
    <p class="sub">${ptEsc(H.name)} · ${ptEsc(FORCES[f].name)} <button type="button" class="ptx-link" id="ptxHero">Change</button></p>
    <div class="ptx-row"><label for="ptxWave">Start at wave <b id="ptxWaveN">${W}</b></label><input type="range" id="ptxWave" min="${PT.min}" max="${PT.max}" step="1" value="${W}"></div>
    <div class="seg ptx-pre" role="group" aria-label="Start wave">${PT.presets.map(n => `<button type="button" data-w="${n}" aria-pressed="${n === W}">Wave ${n}</button>`).join('')}</div>
    <div class="seg ptx-gear" role="group" aria-label="Gear">${PT_GEAR.map(([k, n, t]) => `<button type="button" data-g="${k}" aria-pressed="${k === gear}">${n}<small>${t}</small></button>`).join('')}</div>
    <ul class="ptx-sum" id="ptxSum"></ul>
    <p class="ptx-note">A playtest run posts no scores, counts for nothing in the Chronicles and keeps its own save slot. Its pause menu holds the Loot gallery.</p>
    <button class="btn" id="ptxGo">Start the playtest</button>
    ${sv ? `<button class="btn ghost" id="ptxCont">Continue the playtest<small>Wave ${sv.s.wave}${svH ? ' · ' + ptEsc(svH.name) : ''}</small></button>` : ''}
    <button class="btn ghost" id="ptxBack">Back</button>`, 'ptx-setup');
  const sum = () => {
    const P = ptPlan(W), ch = typeof CHAMP_LEVEL !== 'undefined' ? CHAMP_LEVEL : 15;
    document.getElementById('ptxWaveN').textContent = W;
    document.getElementById('ptxSum').innerHTML = [
      `Level <b>${P.lvl}</b> · <b>${P.tp}</b> talent points (${P.lvl - 1} from levels, ${P.chal} from challenges)`,
      (K => `Gold for a typical army: ${Math.round(PT.gold * 100)}% of a typical run's income to wave ${W}${K.age ? `, less the ${AGES[K.age].name} you start with (tier ${ROMAN[maxTierFor(K.age)]} open)` : ''}`)(ptKeep(W)),
      `<b>${P.rn}</b> Renown`,
      gear === 'none' ? 'An empty bag' : `Gear rolled from the ${Math.floor((W - 1) / 5)} boss${Math.floor((W - 1) / 5) === 1 ? '' : 'es'} passed`,
      P.lvl >= ch ? 'The Champion is ready, with its talents' : `The Champion joins at level ${ch}`,
    ].map(s => `<li>${s}</li>`).join('');
    for (const b of ovp.querySelectorAll('.ptx-pre [data-w]')) b.setAttribute('aria-pressed', +b.dataset.w === W);
    for (const b of ovp.querySelectorAll('.ptx-gear [data-g]')) b.setAttribute('aria-pressed', b.dataset.g === gear);
    ptLs(PT_PREF_KEY, JSON.stringify({ wave: W, gear }));
  };
  const rng = document.getElementById('ptxWave');
  rng.oninput = () => { W = +rng.value; sum(); };
  for (const b of ovp.querySelectorAll('.ptx-pre [data-w]')) b.onclick = () => { W = +b.dataset.w; rng.value = W; sfx('click'); sum(); };
  for (const b of ovp.querySelectorAll('.ptx-gear [data-g]')) b.onclick = () => { gear = b.dataset.g; sfx('click'); sum(); };
  document.getElementById('ptxHero').onclick = () => { sfx('click'); openHeroPicker(() => ptSetup(back), () => ptSetup(back), false); };
  document.getElementById('ptxGo').onclick = () => { if (typeof AudioSys !== 'undefined') AudioSys.init(); sfx('select'); ptStart(hero, W, gear); };
  if (sv) document.getElementById('ptxCont').onclick = () => { if (typeof AudioSys !== 'undefined') AudioSys.init(); sfx('select'); ptContinue(sv); };
  document.getElementById('ptxBack').onclick = () => { sfx('click'); back(); };
  sum();
}

/* ---------- the loot gallery (the pause menu, playtest runs only) ---------- */
// the legendaries given lately (this page only: a playtest writes nothing), so the next playtest gets another
let PT_LEG_SEEN = [];
const ptLegs = () => Object.keys(LEGENDS).filter(k => !LEGENDS[k].school && inPool('legends', k));
const ptSets = () => typeof FSETS !== 'undefined' ? FSETS.filter(S => S.force === G.force && S.pieces.every(p => GEAR_BASES[p[0]])) : [];
function ptHeld(k) {
  const is = it => it && (k.startsWith('L:') ? it.leg === k.slice(2) : !it.leg && it.base === k);
  return (G.loot || []).filter(is).length + (G.towers || []).reduce((a, t) => a + (t.gear || []).filter(is).length + (is(t.charm) ? 1 : 0), 0);
}
function ptTake(k) {
  if (!ptOn() || typeof rnEntOk !== 'function' || !rnEntOk(k)) return null;
  if ((G.loot || []).length >= LOOT_CAP) { toast(`The bag is full (${LOOT_CAP}). Socket or salvage something first.`); sfx('nogold'); return null; }
  const it = rnItem(k); if (typeof ilStamp === 'function') ilStamp(it, ilNow());   // (the gallery's items: the wave's level)
  G.loot.push(it); G.lootNew = (G.lootNew || 0) + 1;
  if ((it.rar | 0) >= 4) G.legN = (G.legN | 0) + 1;
  onDirty(); onSave();
  return it;
}
function ptItemHTML(k) {
  const it = rnItem(k, true), col = typeof itemCol === 'function' ? itemCol(it) : RARITY[it.rar | 0].col, n = ptHeld(k);
  return `<div class="ptx-it" data-k="${ptEsc(k)}" style="--rc:${col}"><img alt="" src="${typeof rnArtURL === 'function' ? rnArtURL(it) : ''}">
    <span class="ptx-tx"><b>${ptEsc(gearName(it))}</b><small>${ptEsc(typeof rnKindLine === 'function' ? rnKindLine(it) : RARITY[it.rar | 0].name)}</small><small class="ptx-held">${n ? n + ' held' : ''}</small></span>
    <button type="button" class="ptx-take" data-k="${ptEsc(k)}">Take</button></div>`;
}
function ptGallery() {
  if (!ptOn() || !G.force) return;
  const F = FORCES[G.force], legs = ptLegs(), sets = ptSets();
  const setHTML = S => `<section class="ptx-set"><h4>${ptEsc(S.name)}<small>${S.unit ? `${S.max} epic pieces on one ${ptEsc(typeof fsetUnitName === 'function' ? fsetUnitName(S) : S.unit)}` : `An army set: ${S.max} epic pieces on different units`}</small></h4>
    <p class="ptx-bon">${(typeof fsetLines === 'function' ? fsetLines(S) : [[2, S.b2]]).map(([k, x]) => `<b>(${k})</b> ${ptEsc(x)}`).join(' ')}</p><div class="ptx-grid">${S.pieces.map(p => ptItemHTML(p[0])).join('')}</div></section>`;
  showOverlay(`<h2 class="ttl">Loot gallery</h2>
    <p class="sub">Playtest · ${ptEsc(F.name)} · <span id="ptxBagN">${G.loot.length}</span> of ${LOOT_CAP} in the bag. Hover an item (long press on touch) for its card; Take puts it in the bag.</p>
    <h3 class="ptx-h">Legendaries <small>${legs.length}</small></h3><div class="ptx-grid">${legs.map(k => ptItemHTML('L:' + k)).join('')}</div>
    <h3 class="ptx-h">Sets <small>${sets.length}</small></h3>${sets.map(setHTML).join('') || '<p class="ptx-note">This force has no sets.</p>'}
    <button class="btn ghost" id="ptxGalBack">Back</button>`, 'ptx-gal');
  for (const b of ovp.querySelectorAll('.ptx-take')) b.onclick = e => {
    e.stopPropagation();
    const it = ptTake(b.dataset.k); if (!it) return;
    sfx('lootDrop', it.rar); toast(`${gearName(it)} is in the bag.`);
    const row = b.closest('.ptx-it'), h = row && row.querySelector('.ptx-held'); if (h) h.textContent = ptHeld(b.dataset.k) + ' held';
    const bn = document.getElementById('ptxBagN'); if (bn) bn.textContent = G.loot.length;
  };
  document.getElementById('ptxGalBack').onclick = () => { sfx('click'); pauseMenu(); };
}
function ptPauseExtras() {
  const tal = document.getElementById('pTal'); if (!tal || document.getElementById('ptxGal')) return;
  const sub = ovp.querySelector('.sub'); if (sub) sub.textContent = `Playtest from wave ${G.playtest.wave} · ` + sub.textContent;
  const box = document.createElement('div'); box.className = 'ptx-pause';
  box.innerHTML = `<button class="btn ghost" id="ptxGal" type="button">Loot gallery<small>Playtest: every legendary and set piece of ${ptEsc(FORCES[G.force] ? FORCES[G.force].name : 'the force')}, to take</small></button>
    <div class="seg" role="group" aria-label="Playtest"><button type="button" id="ptxTp">+5 talent points<small>${G.tp | 0} to spend</small></button><button type="button" id="ptxGold">+1000 gold<small>${G.gold | 0} held</small></button></div>`;
  tal.after(box);
  document.getElementById('ptxGal').onclick = () => { sfx('click'); ptGallery(); };
  document.getElementById('ptxTp').onclick = () => {
    G.tp = (G.tp | 0) + 5; G.tpEarned = (G.tpEarned | 0) + 5; G.talV = (G.talV | 0) + 1; sfx('talentBuy'); onDirty(); onSave();
    document.querySelector('#ptxTp small').textContent = `${G.tp} to spend`;
    const ts = document.querySelector('#pTal small'); if (ts) ts.textContent = `${G.tp} points to spend`;
  };
  document.getElementById('ptxGold').onclick = () => { G.gold = (G.gold | 0) + 1000; sfx('sell'); onDirty(); onSave(); document.querySelector('#ptxGold small').textContent = `${G.gold} held`; };
}

/* ---------- the title's button, the Settings toggle, the HUD label ---------- */
function ptTitleButton() {
  if (!ptToolsOn() || document.getElementById('ptxNew')) return;
  const menu = document.querySelector('.t2-menu'), nb = document.getElementById('oNew'); if (!menu || !nb) return;
  const b = document.createElement('button'); b.type = 'button'; b.id = 'ptxNew'; b.className = 't2-btn ptx-new';
  b.title = 'Start a force run at any wave, with a typical level, talents, gold and gear. Posts no scores; counts for nothing in the Chronicles.';
  b.innerHTML = 'Playtest start<small>Any wave, any gear</small>';
  menu.prepend(b);
  b.onclick = () => { if (typeof AudioSys !== 'undefined') AudioSys.init(); sfx('click'); openHeroPicker(() => ptSetup(titleScreen), titleScreen, false); };
}
function ptSettingsRow() {
  const sb = document.getElementById('sBack'); if (!sb || document.getElementById('ptxTools') || !ptUnlocked()) return;
  const d = document.createElement('div'); d.className = 'seg'; d.setAttribute('role', 'group'); d.setAttribute('aria-label', 'Playtest');
  const lbl = () => ptLs(PT_TOOLS_KEY) === '1' ? 'On' : ptUrlOn() ? 'On for this address' : 'Off';
  d.innerHTML = `<button type="button" id="ptxTools" aria-pressed="${ptToolsOn()}" title="Shows Playtest start on the title: a run begun at any wave with a typical level, talents, gold and gear. Playtest runs post no scores and count for nothing in the Chronicles.">Playtest tools<small>${lbl()}</small></button>`;
  sb.before(d);
  const b = document.getElementById('ptxTools');
  b.onclick = () => { ptLs(PT_TOOLS_KEY, ptLs(PT_TOOLS_KEY) === '1' ? null : '1'); b.setAttribute('aria-pressed', ptToolsOn()); b.querySelector('small').textContent = lbl(); sfx('click'); };
}
function ptHud() {
  if (typeof document === 'undefined') return;
  const on = ptOn() && G.state === 'play';
  let el = document.getElementById('ptxTag');
  if (!el) {
    if (!on) return;
    const bar = document.getElementById('bar'), wv = document.getElementById('hWave'); if (!bar) return;
    el = document.createElement('div'); el.id = 'ptxTag'; el.className = 'res ptx-tag';
    el.title = 'A playtest run: no scores are posted and nothing counts toward the Chronicles.';
    const at = wv && wv.closest('.res'); if (at) at.after(el); else bar.prepend(el);
  }
  if (el.hidden === on) el.hidden = !on;
  if (on) { const t = `Playtest · from wave ${G.playtest.wave}`; if (el.textContent !== t) el.textContent = t; }
}

/* ---------- the end-of-run summary, previewed (ui.js endScreen) ----------
   ptEndDemo(won, { force, hero, wave, camp }) in the console, or ?endscreen=defeat|victory|march beside the playtest key:
   a playtest run with an army, a run's worth of made-up numbers behind it (damage, kills, gold, what got through the
   gate), and then the game's own summary. Nothing is recorded: it is a playtest run. */
let PT_END_CAMP = null;
function ptEndDemo(won, o) {
  if (!ptUnlocked()) return null;
  o = o || {};
  const H = HEROES.find(h => h.id === o.hero) || HEROES.find(h => h.force === (o.force || 'grove')) || HEROES.find(h => h.force) || HEROES[0];
  const W = won ? MAX_WAVE : Math.max(PT.min, Math.min(MAX_WAVE - 1, o.wave || 16));
  ptStart(H.id, W, 'strong');
  if (typeof hideOverlay === 'function') hideOverlay();
  // an army: every kind the force fields, twice, on the first cells that take one
  G.gold = 1e7; G.phase = 'build';
  const kinds = BUILD_ORDER.filter(ty => TOWERS[ty] && !TOWERS[ty].wall), T = [];
  if (Array.isArray(G.unlocked)) G.unlocked = [...new Set(G.unlocked.concat(kinds))];
  const say = onToast; onToast = () => {};
  try {
    for (let j = 2; j < ROWS && T.length < kinds.length * 2; j += 2) for (let i = (j >> 1) % 2; i < COLS && T.length < kinds.length * 2; i += 2) {
      const t = tryBuild(kinds[T.length % kinds.length], i, j); if (t) T.push(t);
    }
  } catch (e) {}
  onToast = say;
  const dmg = [182400, 131900, 96300, 61250, 38800, 27400, 19900, 12600, 8800, 5200, 3100, 1900], k0 = won ? 3.4 : 1;
  G.run = { by: {}, rx: {}, waves: W - 1 };
  T.forEach((t, k) => {
    t.dmg = Math.round((dmg[k] || 900) * k0); t.kills = Math.round(t.dmg / (won ? 950 : 430)); t.tier = Math.min(t.def.tiers.length - 1, won ? 5 - (k > 3) - (k > 8) : k < 2 ? 3 : k < 6 ? 2 : 1);
    const b = G.run.by[t.type] || (G.run.by[t.type] = { hit: 0, dot: 0, rx: 0, relic: 0, abil: 0 }); b.hit += t.dmg * .62; b.abil += t.dmg * .3; b.dot += t.dmg * .08;
  });
  const earned = PT_EARNED[Math.max(0, W - 2)];
  Object.assign(G.stats, { kills: won ? 2964 : 742, leaks: won ? 6 : 20, built: T.length + (won ? 31 : 12), gold: earned, interest: Math.round(earned * .11), aid: won ? 0 : 180, relics: G.loot.length, shop: won ? 4150 : 640 });
  G.gold = won ? 1240 : 235; G.tp = 0; G.lives = won ? 14 : 0;
  // what got through: this wave's own troops
  const seen = [...new Set(makeWave(W, G.diff || 'normal').map(q => q.type))].filter(ty => CREEPS[ty] && !CREEPS[ty].boss);
  if (won) G.stats.leakW = { 37: { n: 4, by: { [seen[0]]: 4 } }, 44: { n: 2, by: { [seen[0]]: 2 } } };
  else {
    const n = [9, 6, 3, 2], hp = [.62, .31, .84, .12], seg = ['gate', 'middle', 'untouched', 'gate'], leaks = [], by = {};
    seen.slice(0, 4).forEach((ty, k) => { by[ty] = n[k]; for (let q = 0; q < n[k]; q++) leaks.push({ t: ty, hp: Math.max(.03, Math.min(1, hp[k] + (q % 3 - 1) * .08)), seg: q % 4 === 3 ? 'middle' : seg[k], big: false, elite: false }); });
    G.stats.leakW = { [W - 4]: { n: 2, by: { [seen[0]]: 2 } }, [W]: { n: leaks.length, by } };
    G.wl = { wave: W, leaks, aside: { 'Armour bars': 8420, 'Shieldbearers\' shields': 5130, 'Spell Ward': 2075, 'War banners': 640 }, dealt: 36800, silS: 14, manaBurn: 0, boss: null };
  }
  PT_END_CAMP = won && o.camp && typeof CAMP_LOCS !== 'undefined' && CAMP_LOCS[1] ? { next: 1, k: 0, huntsOpen: false } : null;
  G.state = won ? 'won' : 'lost';
  try { endScreen(won); } finally { PT_END_CAMP = null; }
  return { hero: H.id, wave: W, units: T.length };
}
function ptEndDemoUrl() {
  let k = ''; try { k = new URLSearchParams(location.search).get('endscreen') || ''; } catch (e) {}
  if (!k || !ptUrlOn()) return;
  let force = ''; try { force = new URLSearchParams(location.search).get('force') || ''; } catch (e) {}
  let n = 0; const iv = setInterval(() => {
    if (++n > 600) return clearInterval(iv);
    if (!document.getElementById('oNew')) return;
    clearInterval(iv);
    try { ptEndDemo(k !== 'defeat', { camp: k === 'march', force: force || undefined }); } catch (e) { console.warn('playtest:', e); }
  }, 200);
}

/* ---------- the hooks (wrappers at load) ---------- */
(function ptHooks() {
  const W = (name, mk) => { const g = typeof globalThis !== 'undefined' ? globalThis : window; if (typeof g[name] !== 'function') return; g[name] = mk(g[name]); };
  // a new run of any kind is not a playtest until ptApply says so
  W('newGame', f => function () { if (typeof G !== 'undefined' && G) G.playtest = null; return f.apply(this, arguments); });
  W('serialize', f => function () { const s = f.apply(this, arguments); if (s && ptOn()) s.playtest = JSON.parse(JSON.stringify(G.playtest)); return s; });
  W('restore', f => function (s) { const r = f.apply(this, arguments); G.playtest = s && s.playtest && typeof s.playtest === 'object' ? Object.assign({}, s.playtest) : null; return r; });
  // saves: a playtest writes only its own slot, never the saved games
  W('saveNow', f => function () { if (ptOn()) return ptSavePut(); return f.apply(this, arguments); });
  W('savesPut', f => function () { if (ptOn()) return; return f.apply(this, arguments); });
  W('saveDrop', f => function (id) { if (ptOn()) { if (id && id === G.runId) ptLs(PT_SAVE_KEY, null); return; } return f.apply(this, arguments); });
  // no scores, bests, rites, Chronicles or journal
  W('recordBest', f => function () { if (!ptOn()) return f.apply(this, arguments); });
  W('chalRecord', f => function () { if (!ptOn()) return f.apply(this, arguments); });
  W('riteRecord', f => function () { return ptOn() ? 0 : f.apply(this, arguments); });
  W('boardPost', f => function () { return ptOn() ? Promise.resolve({ why: 'skip' }) : f.apply(this, arguments); });
  W('boardRunStart', f => function () { if (!ptOn()) return f.apply(this, arguments); });
  W('boardWaveCleared', f => function () { if (!ptOn()) return f.apply(this, arguments); });
  W('boardEndLine', f => function () { return ptOn() ? 'A playtest run: no score is posted, and nothing counts toward the Chronicles.' : f.apply(this, arguments); });
  W('campRunEnd', f => function () { return ptOn() ? PT_END_CAMP : f.apply(this, arguments); });   // (PT_END_CAMP: ptEndDemo's made-up march, shown and never saved)
  W('journalNote', f => function () { if (!ptOn()) return f.apply(this, arguments); });
  // the play log says it is a playtest
  W('plHeader', f => function () {
    const h = f.apply(this, arguments);
    if (h && ptOn()) { h.playtest = Object.assign({}, G.playtest); h.heroName = `${h.heroName || 'no hero'} [Playtest from wave ${G.playtest.wave}, ${G.playtest.gear} gear]`; }
    return h;
  });
  // the menus
  W('titleScreen', f => function () { const r = f.apply(this, arguments); try { ptTitleButton(); } catch (e) { console.warn('playtest:', e); } return r; });
  W('openSettings', f => function () { const r = f.apply(this, arguments); try { ptSettingsRow(); } catch (e) { console.warn('playtest:', e); } return r; });
  W('pauseMenu', f => function () { const r = f.apply(this, arguments); if (ptOn() && G.state === 'play') { try { ptPauseExtras(); } catch (e) { console.warn('playtest:', e); } } return r; });
  if (typeof document !== 'undefined' && typeof document.getElementById === 'function') {
    if (typeof itipBind === 'function') itipBind(document, '.ptx-it[data-k]', el => itemCardHTML(rnItem(el.dataset.k, true), { note: '<p class="itc-eq">Playtest: Take puts it in the bag</p>' }));
    if (typeof setInterval === 'function') setInterval(() => { try { ptHud(); } catch (e) {} }, 400);
    if (typeof window !== 'undefined' && typeof window.addEventListener === 'function') window.addEventListener('pagehide', () => { if (ptOn()) ptSavePut(); });
    if (typeof setTimeout === 'function') setTimeout(() => { try { ptTitleButton(); } catch (e) {} }, 0);
    if (typeof setTimeout === 'function') setTimeout(() => { try { ptEndDemoUrl(); } catch (e) {} }, 0);
  }
})();

/* ================= ITEM LEVELS: what the player sees (the rules are forces_zzzzzzzzz_ilvl.js) =================
   - The card: "Item Level 23" (and "Rite-forged VII", "works at 9 here") on its grey line (itempower.js itemCardHTML).
   - The bag (ui.js): the level in each cell's corner, sorted by level (a Sort: Level / Rarity toggle, remembered), the
     Upgrade button (gold, to the wave's level), Infuse… (pick a higher-level bag item to feed it, then confirm), and on a
     hovered item with a socket open, its level against the socketed one's (green higher, red lower).
   - The gear sheet (gearpanel.js): levels on the bag strip and the Gear rows; a bag item dragged onto a Gear row infuses it.
   - Sets (fsets_ui.js's block): whether every piece is held and the level they share.
   - The boss-loot panel's items come at the wave + IL.boss (rnItem). Loaded last but one (build.sh): it wraps renown.js and
     fsets_ui.js. */

const ilE = s => String(s == null ? '' : s).replace(/[&<>"]/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[ch]));
// the boss-loot panel's items (and the boss tables' cards): the wave + IL.boss
if (typeof rnItem === 'function') {
  const _ilRn = rnItem;
  rnItem = function () { const it = _ilRn.apply(this, arguments); if (it && ilOn()) ilStamp(it, ilNow() + IL.boss); return it; };
}

/* ---------- the bag's order ---------- */
const IL_SORT_KEY = 'runehold.bagsort';
let ilSortMode = null;
function ilSortLv() { if (ilSortMode == null) { try { ilSortMode = localStorage.getItem(IL_SORT_KEY) || 'level'; } catch (e) { ilSortMode = 'level'; } } return ilSortMode !== 'rarity'; }
// the toggle beside the tabs (the bag tab of a force run only)
function ilSortBtn() {
  if (typeof ovp === 'undefined' || !ovp) return;
  let b = document.getElementById('gSort');
  const on = ilOn() && typeof bagTab !== 'undefined' && bagTab === 'bag';
  if (!on) { if (b) b.hidden = true; return; }
  if (!b) {
    const tabs = ovp.querySelector('.bg-tabs'); if (!tabs) return;
    b = document.createElement('button'); b.type = 'button'; b.id = 'gSort'; b.className = 'bg-sort';
    b.onclick = () => { ilSortMode = ilSortLv() ? 'rarity' : 'level'; try { localStorage.setItem(IL_SORT_KEY, ilSortMode); } catch (e) {} sfx('click'); renderBag(); };
    tabs.after(b);
  }
  b.hidden = false; b.textContent = `Sort: ${ilSortLv() ? 'Level' : 'Rarity'}`; b.title = 'Sort the bag by item level or by rarity';
}

/* ---------- comparisons and infusing's preview ---------- */
// the stat lines of `it` against `was` (another item, or the same one at another level): "+18 Damage → +38", green or red
function ilDiffHTML(now, was) {
  const A = Object.fromEntries(itemStats(was)), B = Object.fromEntries(itemStats(now)), keys = IST_ORDER.filter(k => A[k] || B[k]);
  const row = k => { const a = A[k] || 0, b = B[k] || 0, c = b > a ? 'up' : b < a ? 'dn' : '';
    return `<li class="${c}">${a ? ISTAT[k].fmt(a) : '–'} → <b>${b ? ISTAT[k].fmt(b) : '–'}</b> ${ISTAT[k].name}</li>`; };
  return keys.length ? `<ul class="il-dl">${keys.map(row).join('')}</ul>` : '';
}
// a hovered bag item against the socketed one: its level, then its lines against the other's
function ilCompareHTML(it, cur) {
  if (!ilOn() || !it || !cur || it.tome || cur.tome) return '';
  const a = ilOf(it), b = ilOf(cur), c = a > b ? 'up' : a < b ? 'dn' : '';
  return `<p class="il-cmp">Item Level <b class="${c}">${a}</b> <small>(socketed: ${b})</small></p>`;
}
// feeding `feed` into `keep`: the kept item's lines now and after
function ilInfuseNote(keep, feed) {
  const L = ilOf(feed), up = Object.assign({}, keep, { il: L });
  return `<div class="il-inf"><p>Feeds <b>${ilE(gearName(keep))}</b>: Item Level ${ilOf(keep)} → <b>${L}</b>. This item is used up.</p>${ilDiffHTML(up, keep)}</div>`;
}
// the bag's pop-up while infusing: under the item picked to feed (confirm), else under the kept one (cancel)
function bagInfPop(keep) {
  const feed = bagSel && bagSel !== keep && !ilInfuseWhy(keep, bagSel) ? bagSel : null;
  const acts = feed ? [`<button type="button" class="pri" id="gInfY">Infuse · Item Level ${ilOf(feed)}</button>`, `<button type="button" id="gInfN">Cancel</button>`]
    : [`<button type="button" id="gInfN">Cancel infusing</button>`];
  if (!feed) {   // (anchored under the kept item: mark it as the picked cell for bagPopPlace)
    const grid = document.getElementById('gGrid'), c = grid && grid.querySelector(`.bg-cell[data-id="${keep.id}"]`); if (c) c.classList.add('on');
  } else { const grid = document.getElementById('gGrid'), c = grid && grid.querySelector(`.bg-cell[data-id="${keep.id}"]`); if (c) c.classList.remove('on'); }
  bagPop(acts);
  const y = document.getElementById('gInfY'), n = document.getElementById('gInfN');
  if (y) y.onclick = () => { const nm = gearName(feed); if (ilInfuse(keep, feed)) { toast(`${gearName(keep)} rose to Item Level ${keep.il}. ${nm} was used up.`); bagInf = null; bagSel = keep; renderBag(); } };
  if (n) n.onclick = () => { bagInf = null; bagSel = keep; sfx('click'); renderBag(); };
}

/* ---------- sets: the level they share ---------- */
if (typeof fsetBlockHTML === 'function') {
  const _ilSet = fsetBlockHTML;
  fsetBlockHTML = function (S) {
    const h = _ilSet.apply(this, arguments); if (!ilOn() || !h) return h;
    let e = null; try { e = ilSetState()[S.id]; } catch (x) { e = null; }
    const line = e && e.full ? `<p class="il-set on">All ${S.max} held: they share Item Level ${e.L}, and rise together.</p>`
      : '';   /* (said only once the set is whole: the box stays short. Owner, 11 Nov 2026) */
    return h.replace(/<\/div>$/, line + '</div>');
  };
}

/* ---------- the look ---------- */
if (typeof document !== 'undefined' && document.createElement) {
  const css = document.createElement('style');
  css.textContent = `.bg-cell{position:relative}.bg-cell>b.il{position:absolute;right:3px;top:2px;font:700 11px/1 var(--f-ui,sans-serif);color:#f2ead6;text-shadow:0 0 2px #000,0 1px 2px #000;pointer-events:none}
.bg-cell.feed{box-shadow:0 0 0 2px #7fd6ff,0 0 10px rgba(127,214,255,.45)}
.bg-sort{margin-left:auto;margin-right:8px;font:600 12px/1 var(--f-ui,sans-serif);padding:5px 9px;border-radius:4px;color:#d8cfb8;background:#1d1a14;border:1px solid #4a4232;cursor:pointer}
.bg-sort:hover{color:#fff;border-color:#8a7a52}
.il-cmp{margin:4px 0 0;font-size:12.5px;color:#b8b0a0}.il-cmp b.up,.il-dl li.up b{color:#5ee07a}.il-cmp b.dn,.il-dl li.dn b{color:#ff7a6a}
.il-inf{margin:6px 0 0;padding:5px 8px;border-radius:4px;background:rgba(127,214,255,.06);box-shadow:inset 0 0 0 1px rgba(127,214,255,.3)}
.il-inf p{margin:0 0 3px;font-size:12.5px;color:#cfe8f5}.il-dl{margin:2px 0 0;padding:0;list-style:none;font-size:12.5px;color:#9a948a}.il-dl li{margin:1px 0}
.fs-set p.il-set{color:#7d8f8b;font-size:12px}.fs-set p.il-set.on{color:#d8f5ea}
.gp-it .gp-il,.gp-il{font-style:normal;font-weight:600;font-size:11px;color:#d8cfb8;padding:0 4px;border-radius:6px;box-shadow:inset 0 0 0 1px #4a4232;margin-left:3px}
.gp-it.gp-drop{box-shadow:inset 0 0 0 2px #7fd6ff}.gp-it.gp-nodrop{box-shadow:inset 0 0 0 2px #a04a3a}
.gp-infq{margin:4px 0 6px;padding:6px 8px;border-radius:4px;background:rgba(127,214,255,.08);box-shadow:inset 0 0 0 1px rgba(127,214,255,.4)}
.gp-infq p{margin:0 0 5px;font-size:12.5px;color:#cfe8f5}.gp-infq button{margin-right:6px}`;
  (document.head || document.documentElement).append(css);
}

