  return `<div class="icmp-d"><p class="icmp-h">${head} · ${icSockName(p)}</p>${C.rows.length ? `<ul>${C.rows.map(li).join('')}</ul>` : ''}${sp ? `<p class="icmp-s">Spell damage</p><ul>${sp}</ul>` : ''}${typeof ohCmpHTML === 'function' ? ohCmpHTML(p, it) : ''}${none}${cyc}</div>`;
