  const cellOf = e => { const el = e.target && e.target.closest ? e.target.closest('.gp-body .gp-bc[data-bi], .gp-body .wp-bc[data-wbi], #gGrid .bg-cell[data-id], #gGrid .wp-bc[data-wbi]') : null; return el; };
